struct TranscriptChunk: Sendable {
    let id: String
    let analysisAssetId: String
    let segmentFingerprint: String
    let chunkIndex: Int
    let startTime: Double
    let endTime: Double
    let text: String
    let normalizedText: String
    let pass: String // fast | final
    let modelVersion: String
    let transcriptVersion: String?   // nil for fast-pass chunks (version computed on final)
    let atomOrdinal: Int?            // nil for fast-pass chunks
    let weakAnchorMetadata: TranscriptWeakAnchorMetadata?
    let speakerId: Int?              // B7: validated speaker label, nil when unavailable
    let avgConfidence: Float?        // ASR average confidence, nil on legacy/unavailable rows

    init(
        id: String,
        analysisAssetId: String,
        segmentFingerprint: String,
        chunkIndex: Int,
        startTime: Double,
        endTime: Double,
        text: String,
        normalizedText: String,
        pass: String,
        modelVersion: String,
        transcriptVersion: String?,
        atomOrdinal: Int?,
        weakAnchorMetadata: TranscriptWeakAnchorMetadata? = nil,
        speakerId: Int? = nil,
        avgConfidence: Float? = nil
    ) {
        self.id = id
        self.analysisAssetId = analysisAssetId
        self.segmentFingerprint = segmentFingerprint
        self.chunkIndex = chunkIndex
        self.startTime = startTime
        self.endTime = endTime
        self.text = text
        self.normalizedText = normalizedText
        self.pass = pass
        self.modelVersion = modelVersion
        self.transcriptVersion = transcriptVersion
        self.atomOrdinal = atomOrdinal
        self.weakAnchorMetadata = weakAnchorMetadata
        self.speakerId = speakerId
        self.avgConfidence = Self.sanitizedAvgConfidence(avgConfidence)
    }

    static func sanitizedAvgConfidence(_ value: Float?) -> Float? {
        guard let value, value.isFinite else { return nil }
        return min(max(value, 0), 1)
    }
}

struct AdWindow: Sendable {
    let id: String
    let analysisAssetId: String
    let startTime: Double
    let endTime: Double
    /// playhead-ar60: the DETECTION confidence — "how strongly does the
    /// evidence say this span is an ad". Every producer writes this quantity:
    /// the hot-path classifier writes `adProbability`, the segment aggregator
    /// its `segmentScore`, the mark composers their capped mark confidence,
    /// byte-exact rediff and user marks write `1.0`, and (since ar60) the
    /// fusion path writes `DecisionResult.proposalConfidence`.
    ///
    /// It is NOT the number an actuator may gate on. Until ar60 the fusion
    /// path wrote `DecisionResult.skipConfidence` — the post-correction
    /// ACTUATION number — into this same column, so the two quantities shared
    /// one field and every reader saw whichever the producer happened to mean:
    /// on the 2026-08-02 device pull that was 40 of 104 rows, and 5 of them
    /// were admitted to the cross-launch preload only because an unrelated
    /// user correction on the same asset had inflated the value past the 0.7
    /// DETECTOR floor. Actuation now lives in `skipConfidence`; read it
    /// through ``actuationConfidence`` so a producer that records no separate
    /// actuation number still resolves to something.
    let confidence: Double
    /// playhead-ar60: the ACTUATION confidence — "how much permission does the
    /// system have to act on this span", i.e. detection after calibration and
    /// after the user-correction factor. Written by the fusion path only.
    ///
    /// `nil` means the producer has exactly one number and it is in
    /// `confidence`: the hot path, the mark composers, rediff mints, user
    /// marks, and every row written before the V47 split. Do not read this
    /// field directly for a gate — use ``actuationConfidence``.
    let skipConfidence: Double?
    let boundaryState: String
    let decisionState: String
    let detectorVersion: String
    let advertiser: String?
    let product: String?
    let adDescription: String?
    let evidenceText: String?
    let evidenceStartTime: Double?
    let metadataSource: String
    let metadataConfidence: Double?
    let metadataPromptVersion: String?
    let wasSkipped: Bool
    let userDismissedBanner: Bool
    let evidenceSources: String?
    let eligibilityGate: String?
    /// playhead-epfk: top `AdCatalogStore.matches(...)` similarity in
    /// `[0, 1]` for this window's acoustic fingerprint, computed at
    /// fusion time. `nil` when the catalog store was unavailable or the
    /// fingerprint/show scope could not be evaluated; `0.0` when an
    /// exact-show query ran but no match cleared the floor. Surfaced into
    /// `corpus-export.jsonl` so NARL eval can measure the
    /// fingerprint-store firing rate independently from the
    /// transcript-token catalog (which shares the `.catalog` evidence
    /// source label). Persisted on the row so a re-export of an old
    /// device DB doesn't lose the value.
    let catalogStoreMatchSimilarity: Double?
    /// Versioned fingerprint semantics used for the match. Nil means no
    /// compatible catalog match was admitted.
    let catalogFingerprintVersion: Int?
    /// Durable catalog row identity and show scope used for the match. These
    /// fields make a later veto auditable and let it revoke the exact learned
    /// row instead of guessing from similarity alone.
    let catalogMatchedEntryId: String?
    let catalogMatchedShowId: String?
    /// Authoritative lifecycle that originally admitted the matched row.
    let catalogMatchedLearningSource: String?
    let catalogMatchedLearningLifecycle: String?
    /// playhead-hdgk: the per-edge auto-skip anchor tier (an
    /// `AutoSkipEdgeAnchor` raw value — `"rediffByteExact"` /
    /// `"stingerSnapped"` / `"unanchored"`) derived at fusion/decision-build
    /// time, so `SkipOrchestrator` can classify each edge by its real
    /// provenance instead of defaulting to `.unanchored`. Non-optional with a
    /// `"unanchored"` default: pre-hdgk rows and non-fusion producers (hot
    /// path, imported shares, synthetic user marks) carry the conservative
    /// default, under which the (dormant) edge-padding policy auto-skips
    /// nothing. Kept as a raw String — like `eligibilityGate` — so the
    /// persistence layer stays decoupled from the orchestrator's enum for I/O.
    let startEdgeAnchor: String
    let endEdgeAnchor: String

    /// playhead-ar60: the confidence an ACTUATOR must gate on — the persisted
    /// `skipConfidence` when the producer recorded one, otherwise
    /// `confidence`.
    ///
    /// The fallback is what makes the V47 split behaviour-preserving: a
    /// producer with a single number (hot path, mark composers, rediff, user
    /// marks) and every pre-V47 row resolve to exactly the value the actuation
    /// readers saw before the split. Only the fusion path, which genuinely has
    /// two numbers, now hands them a different one from `confidence`.
    var actuationConfidence: Double { skipConfidence ?? confidence }

    /// playhead-ar60: the ACTUATION number is a usable probability.
    ///
    /// The runtime already fails closed on a malformed `confidence`
    /// (`SkipOrchestrator.hasValidRuntimeWindowMaterial`); V47 added a second
    /// number that a skip gate reads, so it needs the same door. Vacuously
    /// true whenever `skipConfidence` is nil, because then
    /// `actuationConfidence` IS `confidence` and the existing check covers it.
    var carriesUsableActuationConfidence: Bool {
        actuationConfidence.isFinite && (0...1).contains(actuationConfidence)
    }

    /// A non-zero score or any match-provenance field claims that catalog
    /// evidence participated in this decision. Invalid non-finite values also
    /// count as a claim so corrupted rows fail closed instead of slipping
    /// through the zero-score compatibility case.
    var claimsCatalogMatch: Bool {
        if let similarity = catalogStoreMatchSimilarity,
           !similarity.isFinite || similarity != 0 {
            return true
        }
        return catalogFingerprintVersion != nil
            || catalogMatchedEntryId != nil
            || catalogMatchedShowId != nil
            || catalogMatchedLearningSource != nil
            || catalogMatchedLearningLifecycle != nil
    }

    /// Complete provenance required before a persisted catalog-assisted
    /// decision may remain in an automatic tier. Runtime admission requires a
    /// canonical active show; nil/blank identity fails closed.
    func hasCompatibleCatalogMatchProvenance(
        expectedShowId: String?
    ) -> Bool {
        guard let similarity = catalogStoreMatchSimilarity,
              similarity.isFinite,
              similarity >= Double(AdCatalogStore.defaultSimilarityFloor),
              similarity <= 1,
              catalogFingerprintVersion
                == CatalogFingerprintVersion.currentCatalog.rawValue,
              let entryId = catalogMatchedEntryId,
              UUID(uuidString: entryId) != nil,
              let showId = catalogMatchedShowId,
              RecurrenceMaterialIdentity.canonicalIdentifier(showId) != nil,
              let sourceRaw = catalogMatchedLearningSource,
              let source = CatalogLearningSource(rawValue: sourceRaw),
              let lifecycleRaw = catalogMatchedLearningLifecycle,
              let lifecycle = CatalogLearningLifecycle(rawValue: lifecycleRaw),
              source.authoritativeLifecycle == lifecycle else {
            return false
        }
        guard let canonicalExpected =
                RecurrenceMaterialIdentity.canonicalIdentifier(
                    expectedShowId
                ),
              showId == canonicalExpected else {
            return false
        }
        return true
    }

    init(
        id: String,
        analysisAssetId: String,
        startTime: Double,
        endTime: Double,
        confidence: Double,
        // playhead-ar60: defaulted so the single-number producers (hot path,
        // mark composers, rediff mints, user marks, copy-with helpers) keep
        // their call sites AND their semantics — `nil` means "this producer
        // has one number and it is `confidence`", which is exactly true of
        // every one of them.
        skipConfidence: Double? = nil,
        boundaryState: String,
        decisionState: String,
        detectorVersion: String,
        advertiser: String?,
        product: String?,
        adDescription: String?,
        evidenceText: String?,
        evidenceStartTime: Double?,
        metadataSource: String,
        metadataConfidence: Double?,
        metadataPromptVersion: String?,
        wasSkipped: Bool,
        userDismissedBanner: Bool,
        evidenceSources: String? = nil,
        eligibilityGate: String? = nil,
        catalogStoreMatchSimilarity: Double? = nil,
        catalogFingerprintVersion: Int? = nil,
        catalogMatchedEntryId: String? = nil,
        catalogMatchedShowId: String? = nil,
        catalogMatchedLearningSource: String? = nil,
        catalogMatchedLearningLifecycle: String? = nil,
        startEdgeAnchor: String = AutoSkipEdgeAnchor.unanchored.rawValue,
        endEdgeAnchor: String = AutoSkipEdgeAnchor.unanchored.rawValue
    ) {
        self.id = id
        self.analysisAssetId = analysisAssetId
        self.startTime = startTime
        self.endTime = endTime
        self.confidence = confidence
        self.skipConfidence = skipConfidence
        self.boundaryState = boundaryState
        self.decisionState = decisionState
        self.detectorVersion = detectorVersion
        self.advertiser = advertiser
        self.product = product
        self.adDescription = adDescription
        self.evidenceText = evidenceText
        self.evidenceStartTime = evidenceStartTime
        self.metadataSource = metadataSource
        self.metadataConfidence = metadataConfidence
        self.metadataPromptVersion = metadataPromptVersion
        self.wasSkipped = wasSkipped
        self.userDismissedBanner = userDismissedBanner
        self.evidenceSources = evidenceSources
        self.eligibilityGate = eligibilityGate
        self.catalogStoreMatchSimilarity = catalogStoreMatchSimilarity
        self.catalogFingerprintVersion = catalogFingerprintVersion
        self.catalogMatchedEntryId = catalogMatchedEntryId
        self.catalogMatchedShowId = catalogMatchedShowId
        self.catalogMatchedLearningSource = catalogMatchedLearningSource
        self.catalogMatchedLearningLifecycle =
            catalogMatchedLearningLifecycle
        self.startEdgeAnchor = startEdgeAnchor
        self.endEdgeAnchor = endEdgeAnchor
    }
}

struct ResponseIndependentAssetEgressProjection: Sendable {
    let windows: [AdWindow]
    let decodedSpans: [DecodedSpan]
    let listenRewinds: [AdListenRewindRow]
    let confirmedAdCoverageEndTime: Double?
}

// Bug 5 (skip-cues-deletion): the `SkipCue` model and `skip_cues` table
// were deleted. `SkipOrchestrator.beginEpisode` now reads
// confirmed-confidence `AdWindow` rows directly.

/// playhead-hygc.1.2: canonical pipeline-progress read model used by Activity
/// rows and the dogfood diagnostics snapshot.
///
/// Reconciles per-asset coverage from the most trustworthy persisted artifact
/// available at read time, without rewriting the underlying watermark columns
/// (long-term watermark repair lives in a separate state-machine bead).
///
/// Two distinct fast-transcript numbers are exposed because they answer
/// different questions:
///   - ``fastTranscriptCoveredSec`` is the **interval-unioned seconds of fast
///     transcript actually present** for the asset. Overlapping chunks count
///     once; gaps are excluded. This is the "how much fast text is real?"
///     answer that drives the displayed transcript fraction.
///   - ``fastTranscriptCoverageEndSec`` is the **high-water max(endTime)** of
///     fast chunks (or the asset watermark when no chunks landed yet). This
///     answers "how far into the audio has the runner reached?" — a useful
///     supplementary signal that does not collapse on gaps.
/// Summing chunk durations would overstate overlapping chunks AND
/// under-explain gaps, so the read model keeps both numbers explicit.
///
/// Each scalar is paired with a ``CoverageProvenance`` tag describing where
/// the value came from: callers surface this in dogfood diagnostics so the
/// "is this 39% from real chunks or a stale watermark?" question has an
/// answer that doesn't require database forensics.
struct AnalysisCoverageSummary: Sendable, Equatable {

    /// Provenance tag for a derived coverage scalar. Exactly the surface
    /// described in the bead spec; new sources require a deliberate enum
    /// case to keep the dogfood schema and downstream NARL eval aligned.
    enum CoverageProvenance: String, Sendable, Equatable {
        /// Value derived from `transcript_chunks` rows whose `pass = 'fast'`.
        case fastTranscriptChunks = "fast_transcript_chunks"
        /// Value derived from `transcript_chunks` rows whose `pass = 'final'`.
        case finalPassChunks = "final_pass_chunks"
        /// Value read directly from one of the `analysis_assets` watermark
        /// columns (`fastTranscriptCoverageEndTime`, `featureCoverageEndTime`,
        /// `confirmedAdCoverageEndTime`, `finalPassCoverageEndTime`).
        case assetWatermark = "asset_watermark"
        /// Value derived from `ad_windows` rows (e.g. `MAX(endTime)`).
        case adWindows = "ad_windows"
        /// Value derived from cached audio state (download-progress side).
        case cachedAudio = "cached_audio"
        /// playhead-pz32: value derived from `semantic_scan_results` rows —
        /// the seconds of audio a semantic ad scan actually examined.
        case semanticScanResults = "semantic_scan_results"
        /// Coverage genuinely unknown — no chunks, no watermark, no ad
        /// windows present. Surfaces as `nil` fractions / `--%` rather than
        /// a synthetic 0% bar.
        case unknown
    }

    let assetId: String
    /// The episode's DECLARED duration — `analysis_assets.episodeDurationSec`,
    /// which comes off the feed or a decode probe, not off the transcript.
    /// playhead-x0lb: typed as ``EpisodeSeconds`` because it is the denominator
    /// of every ratio on this struct, and a ratio whose denominator can be
    /// swapped for a watermark is instance 9 of the defect catalogue.
    let episodeDurationSec: EpisodeSeconds?
    /// Interval-unioned seconds of fast transcript actually present — an AREA.
    /// `nil` when no fast chunks landed AND no watermark is recorded.
    let fastTranscriptCoveredSec: CoveredSeconds?
    let fastTranscriptCoveredSource: CoverageProvenance
    /// `MAX(endTime)` of fast chunks, or the asset watermark when no chunks
    /// landed yet — a REACH, not an area. `nil` when both signals are absent.
    let fastTranscriptCoverageEndSec: WatermarkSeconds?
    let fastTranscriptCoverageEndSource: CoverageProvenance
    /// playhead-x0lb R1: ``FrontierSeconds``, not the transcript's watermark.
    /// Feature extraction sweeps the whole episode independently of the
    /// semantic scan, so this reaches 100 % while most audio has never been
    /// screened — instance 9's own ingredient.
    let featureCoverageEndSec: FrontierSeconds?
    let featureCoverageEndSource: CoverageProvenance
    /// playhead-x0lb R1: ``FrontierSeconds``. Not coverage at all — see the
    /// ``adScanCoveredSec`` doc below, which had to say so in prose.
    let confirmedAdCoverageEndSec: FrontierSeconds?
    let confirmedAdCoverageEndSource: CoverageProvenance
    /// `MAX(endTime)` over `pass='final'` chunks, falling back to the asset
    /// watermark column when chunks are absent. `nil` when both are absent.
    let finalPassCoverageEndSec: WatermarkSeconds?
    let finalPassCoverageEndSource: CoverageProvenance
    /// playhead-sd71: gap-aware **analyzed-coverage AREA** — the
    /// interval-unioned fast-transcript seconds that fall at or before the
    /// analysis frontier (`max(featureCoverageEndSec, confirmedAdCoverageEndSec)`).
    /// This is the honest "how much has actually been analyzed?" answer:
    /// you cannot analyze audio you have not transcribed, so it is a subset
    /// of ``fastTranscriptCoveredSec`` and is therefore mathematically
    /// `<= fastTranscriptCoveredSec` by construction. Drives the AN pipeline
    /// fraction, replacing the old high-water watermark that could overshoot
    /// a gappy transcript (the "AN 100% / TX 39%" antipattern). `nil` when
    /// the analysis frontier is unknown OR the transcript coverage is
    /// unknown (mirrors ``fastTranscriptCoveredSec``'s nil semantics), so
    /// AN renders as `--%` rather than a synthetic 0%.
    let analysisCoveredSec: AnalyzedSeconds?
    /// playhead-pz32: seconds of audio a **semantic ad scan actually examined**.
    ///
    /// Precisely: the interval union of `semantic_scan_results` windows on the
    /// coverage lane (``SemanticScanCoverage/coverageScanPass``) that produced a
    /// verdict (``SemanticScanResult/didExamineWindow(status:errorContext:)`` —
    /// the status semantics MINUS no-work sentinels), INTERSECTED with the
    /// transcribed region (sub-ad-width gaps bridged, see
    /// ``AnalysisCoverageMath/adScanBridgeableGapSec``). The intersection is what
    /// stops a single window's bounds from claiming a large untranscribed block
    /// its prompt never contained; the bridging is what stops every
    /// inter-utterance breath from counting as unscanned.
    ///
    /// playhead-9y9e: "the transcribed region" means BOTH passes. It was the
    /// fast pass alone, which on the 2026-08-03 device pull put a ceiling below
    /// the 0.98 completion floor under this fraction for NINE of twelve assets,
    /// of which this change lifts FOUR over it — see the `transcribedRegion`
    /// block in ``fetchCoverageSummariesByAssetIds(_:)`` for the split.
    ///
    /// (R2 review: this line read "four of twelve assets", which is the number
    /// LIFTED, not the number capped. R1 corrected that count at the
    /// `transcribedRegion` block and this sentence — which points AT that
    /// block — was left contradicting it.)
    ///
    /// This is the only persisted quantity that answers "how much of this
    /// episode has been read for ads?". It is deliberately NOT any of the
    /// other scalars on this summary:
    ///   * ``featureCoverageEndSec`` is the acoustic/DSP feature-extraction
    ///     watermark. Feature extraction sweeps the whole episode
    ///     independently of the semantic scan, so it reaches 100% while most
    ///     audio has never been screened for ads.
    ///   * ``confirmedAdCoverageEndSec`` is not coverage at all — it is
    ///     `max(endTime)` OF DETECTED AD WINDOWS. One late-placed detection
    ///     pushes it to the end of the episode with almost nothing scanned,
    ///     which has the perverse consequence that AN EPISODE WHERE
    ///     DETECTION DID WORSE CAN LOOK MORE COMPLETE.
    ///   * ``analysisCoveredSec`` is transcript-union-clipped-to-that-same
    ///     frontier, so it inherits both problems in a gap-aware form.
    ///
    /// `nil` when no coverage-lane scan row exists for the asset at all
    /// (the scan has not started, or its rows were invalidated by a cohort
    /// bump) — never a synthetic 0, so a caller can distinguish "measured
    /// zero" from "no measurement". Both must render as not-ready.
    let adScanCoveredSec: AdScanSeconds?
    let adScanCoveredSource: CoverageProvenance

    /// playhead-nffz: the SUPREMUM of ``adScanCoveredSec`` on the transcript that
    /// exists today — the bridged transcribed area, both passes.
    ///
    /// It is not a second estimate of coverage. It is the very region
    /// ``adScanCoveredSec`` is intersected with (see that doc and
    /// ``AdScanSeconds/init(examined:within:bridging:)``), so
    /// `adScanCoveredSec <= adScanCeilingSec` holds by CONSTRUCTION rather than
    /// by observation, and the difference between the two is the only audio a
    /// further scan could ever add.
    ///
    /// **Why it had to become a published quantity.** ``adScanFraction``'s
    /// numerator is bounded by this area and its denominator is the DECLARED
    /// DURATION, while the floor that judges it
    /// (``AnalysisJobRunner/semanticBackfillSufficientAdScanFraction``, 0.98) is
    /// also stated over the duration. An episode whose transcript covers less
    /// than 0.98 of its duration therefore cannot clear that floor **however
    /// perfectly it is scanned** — two populations compared as one, which is this
    /// repo's standing defect class. Measured on the 2026-08-14 device pull,
    /// three of nine assets are in that state (C065AD03 scanned 0.4384 against a
    /// ceiling of 0.4436; AA6CD430 0.8600 / 0.8961; C0610BF9 0.9264 / 0.9341) and
    /// on the 2026-08-11 pull all five are (0.0257/0.0697, 0.0691/0.9031,
    /// 0.2544/0.2575, 0.8202/0.8300, 0.9264/0.9274). Publishing the bound is what
    /// lets the coverage terminal say WHICH of the two constraints bound —
    /// see ``BackfillJobRunner/UnderCoverageConstraint``.
    ///
    /// `nil` when there is no transcript evidence of any kind (no chunk of either
    /// pass and no fast watermark), never a synthetic 0: "nothing has been
    /// transcribed yet" and "this episode's transcript is empty" are different
    /// claims, and only the second may be read as a ceiling.
    let adScanCeilingSec: BridgedTranscriptSeconds?

    /// playhead-pz32: ``adScanCoveredSec`` as a fraction of the episode's
    /// duration, clamped to `[0, 1]`. `nil` when the quantity is not honestly
    /// measurable — an unmeasurable episode must read as not-ready, never ready.
    ///
    /// Three ways it is not measurable, all returning `nil`:
    ///   * scan coverage unknown or non-finite;
    ///   * duration missing, non-finite, or non-positive (legacy rows,
    ///     placeholder rows pre-decode) — never a divide-by-zero;
    ///   * coverage exceeding the duration by more than
    ///     ``adScanDurationToleranceSec(episodeDurationSec:)``. A ratio above 1
    ///     means the numerator and the denominator describe different audio,
    ///     which happens for real: a feed can declare a duration wildly shorter
    ///     than the file (the 2026-04-27 libsyn/flightcast episode declared 704 s
    ///     for ~9,700 s of audio; four of the five assets in the 2026-04-25
    ///     device capture have a declared duration shorter than their transcript
    ///     span), and terminal rows carrying `transcript 1.163, feature 1.724`
    ///     have been observed (playhead-csbq). Clamping such an overshoot to
    ///     exactly `1.0` would turn a broken denominator into a confident ✓ on a
    ///     fraction of the audio, so a disagreement that large reads as
    ///     unmeasurable instead.
    ///   * a duration CONTRADICTED by the transcript's own reach. Measured on the
    ///     2026-04-25 device capture, asset E8F0F867 declares 552.9 s while its
    ///     fast transcript reaches 3,810 s, and its ad scan examined 563.8 s of
    ///     that. The ratio alone (563.8 / 552.9) is indistinguishable from a
    ///     legitimately-complete short episode, so the overshoot check above lets
    ///     it through and it would render a confident ✓ on 14.8% of the audio. A
    ///     transcript that reaches far past the declared duration is proof the
    ///     denominator is wrong — the same judgement
    ///     ``FastTranscriptCoverageInvariant`` already makes — so the fraction is
    ///     withheld until the duration is repaired (`PlayheadRuntime`'s
    ///     duration-backfill sweep).
    ///
    ///     playhead-9y9e (R2 review): **"the transcript's reach" here means the
    ///     DEEPER of the two passes**, because playhead-9y9e widened
    ///     ``adScanCoveredSec``'s bound from the fast union to both passes and
    ///     this guard has to measure the same region the numerator is drawn
    ///     from. Reading the FAST reach alone left the check incoherent in
    ///     exactly the population this bead exists to serve: a final-pass-heavy
    ///     asset whose final pass runs far past a wrong declared duration, and
    ///     whose short fast reach keeps the guard silent, would divide a
    ///     duration-sized numerator by that wrong duration and render a
    ///     confident ✓ — the E8F0F867 shape reproduced through the other pass.
    ///     No asset on the 2026-08-03 pull exercises it (every
    ///     `finalPassCoverageEndSec` is inside the tolerance), so this is a rail,
    ///     not a repair; the fixture is
    ///     `finalPassReachPastDurationWithholdsTheFraction` and mutation RT14.
    ///
    ///     playhead-9y9e (R3 review): the final term counts only when its
    ///     provenance is `.finalPassChunks`. A final WATERMARK with no chunks
    ///     behind it must not withhold anything — see the comment at the guard
    ///     itself, and `finalPassWatermarkWithoutChunksDoesNotWithhold` /
    ///     mutation RT16.
    ///
    /// playhead-x0lb: the return type is ``ReachRatio``, not `Double`. Its
    /// numerator is an ``AdScanSeconds`` AREA and its denominator is the
    /// DECLARED ``EpisodeSeconds`` duration, both named at the only constructor
    /// (``ReachRatio/init(examined:ofDeclaredDuration:)``), so a
    /// ``DensityRatio`` — the transcribed area over the same duration, which is
    /// what playhead-fil5 R3 divided and called reach — can no longer be
    /// supplied to any consumer that wants this one. The two coincide on
    /// single-chunk fixtures, which is why every test passed while nought of
    /// twelve field assets cleared the gate.
    var adScanFraction: ReachRatio? {
        guard let adScanCoveredSec,
              adScanCoveredSec.isFinite,
              adScanCoveredSec.rawValue >= 0,
              let episodeDurationSec,
              episodeDurationSec.isFinite,
              episodeDurationSec.rawValue > 0 else {
            return nil
        }
        let tolerance = Self.adScanDurationToleranceSec(episodeDurationSec: episodeDurationSec)
        // playhead-x0lb: an AREA compared against a DURATION, deliberately —
        // this is the one place the comparison is meaningful, because an area
        // that exceeds the whole declared duration is proof the two describe
        // different audio.
        //
        // R4 review: through ``AdScanSeconds/exceeds(_:byMoreThan:)``, not in
        // raw values. Written inline the comparison accepted every area on the
        // summary: probe PA2 drove it from `fastTranscriptCoveredSec` — an area
        // this guard is not protecting — and it COMPILED, so the check meant to
        // catch a numerator describing different audio could be pointed away
        // from the numerator entirely. Rail TY22.
        guard !adScanCoveredSec.exceeds(episodeDurationSec, byMoreThan: tolerance) else { return nil }
        // A transcript reaching far past the declared duration means the
        // denominator describes different audio than the numerator, even when
        // their RATIO looks healthy. Under-claim rather than divide by a number
        // the transcript has already disproved.
        //
        // BOTH passes (playhead-9y9e R2 review): the numerator's bound spans
        // both, so the reach this compares against the duration must too. See
        // the `adScanFraction` doc above for the shape that made a fast-only
        // read incoherent. A missing or non-finite reach on either side is
        // simply absent from the max — it is not evidence of anything.
        //
        // THE FINAL TERM IS ADMITTED ONLY ON CHUNK EVIDENCE (playhead-9y9e R3
        // review), and the asymmetry with the fast term is deliberate.
        // `finalPassCoverageEndSec` falls back to the
        // `analysis_assets.finalPassCoverageEndTime` COLUMN when no final chunk
        // is on disk — playhead-0sro's "watermark outliving the rows it claims"
        // shape, the same one `transcribedRegion` and
        // `watermarkWithoutChunksStillFails` are built around, and reachable
        // because playhead-wvdz's chunk deletion outlives the asset row. A stale
        // column would then WITHHOLD a fraction that is fine, i.e. make an
        // episode less ready — the one direction this bead's widening promised
        // never to move. The fast term keeps its existing behaviour: it was
        // already load-bearing before this bead and changing it is not this
        // bead's business. Every asset on the 2026-08-03 pull that has a final
        // watermark also has final chunks, and chunks win, so this guard is
        // latent there — a rail, not a repair.
        //
        // playhead-nffz: the rule itself now lives in
        // ``declaredDurationIsDisprovedByTranscriptReach(tolerance:)``, because
        // ``adScanCeilingFraction`` has to apply the IDENTICAL guard — the two
        // fractions are measured against the same floor, so an episode either
        // one withholds and the other does not is an episode that falls between
        // two rulers. Everything the paragraphs above say about it is unchanged;
        // it is stated once instead of twice. Rails TY23 and the R4 probe PA3
        // record still apply, at the new site.
        guard !declaredDurationIsDisprovedByTranscriptReach(tolerance: tolerance) else { return nil }
        return ReachRatio(examined: adScanCoveredSec, ofDeclaredDuration: episodeDurationSec)
    }

    /// playhead-nffz: ``adScanCeilingSec`` as a fraction of the same declared
    /// duration — the largest value ``adScanFraction`` can ever report on this
    /// transcript.
    ///
    /// **One ruler, two readers.** The withholding guards are the SAME guards, in
    /// the same order, reached through the same predicate
    /// (``declaredDurationIsDisprovedByTranscriptReach``): a ceiling published
    /// under looser guards than the measurement it bounds would be a ceiling that
    /// exists for episodes whose measurement does not, and the one comparison
    /// this quantity exists for — ceiling against the ad-scan floor — would then
    /// be made on a denominator ``adScanFraction`` has already rejected.
    ///
    /// **It does NOT require a coverage-lane row, and that asymmetry is the
    /// point.** ``adScanFraction`` is `nil` until something has scanned; the
    /// ceiling is a property of the TRANSCRIPT and is knowable before the first
    /// window. `nil` here means the transcript is unknown or the duration is
    /// unusable — never "no scan yet".
    ///
    /// **What it reads if the thing it measures never happened.** An asset with a
    /// real duration and no transcript at all reads `nil` (see
    /// ``adScanCeilingSec``), not 0 — so nothing downstream can read "no
    /// transcript has landed yet" as "this episode can never be scanned".
    var adScanCeilingFraction: ReachRatio? {
        guard let adScanCeilingSec,
              adScanCeilingSec.isFinite,
              adScanCeilingSec.rawValue >= 0,
              let episodeDurationSec,
              episodeDurationSec.isFinite,
              episodeDurationSec.rawValue > 0 else {
            return nil
        }
        let tolerance = Self.adScanDurationToleranceSec(episodeDurationSec: episodeDurationSec)
        // The ceiling is an AREA and the duration a DURATION, compared for the
        // same reason `adScanFraction` compares its own numerator: an area past
        // the whole declared duration proves the two describe different audio.
        guard !adScanCeilingSec.exceeds(episodeDurationSec, byMoreThan: tolerance) else { return nil }
        guard !declaredDurationIsDisprovedByTranscriptReach(tolerance: tolerance) else { return nil }
        return ReachRatio(ceiling: adScanCeilingSec, ofDeclaredDuration: episodeDurationSec)
    }

    /// playhead-nffz: the transcript-reach guard shared by ``adScanFraction`` and
    /// ``adScanCeilingFraction``, extracted so there is ONE expression of it.
    ///
    /// Two copies of this rule that happen to agree is precisely how the
    /// certainty tier and its consumers came apart (playhead-6qvf), and the
    /// hazard is sharper here than usual: the two fractions are compared against
    /// the same floor, so a divergence in when each is withheld is invisible
    /// until an episode falls into the gap between them.
    ///
    /// See ``adScanFraction`` for the full argument, the E8F0F867 witness and the
    /// `.finalPassChunks`-only admission of the final term.
    private func declaredDurationIsDisprovedByTranscriptReach(tolerance: Double) -> Bool {
        guard let episodeDurationSec else { return false }
        // THE FINAL TERM IS ADMITTED ONLY ON CHUNK EVIDENCE (playhead-9y9e R3
        // review) — a stale watermark column would WITHHOLD a fraction that is
        // fine, i.e. make an episode less ready.
        let finalReach = finalPassCoverageEndSource == .finalPassChunks
            ? finalPassCoverageEndSec
            : nil
        // playhead-x0lb: these are ``WatermarkSeconds`` — REACH, not area — and
        // that is exactly the property this guard needs. An AREA can never
        // disprove a duration (a gappy transcript's area is legitimately small);
        // only a reach PAST the declared end can.
        // playhead-x0lb R1: the element type is written out. Without it a
        // substitution into this literal makes the type-checker give up
        // ('failed to produce diagnostic'), and a compile failure nobody can
        // name is not a kill the UNTYPEABLE battery is allowed to credit.
        let transcriptReach: WatermarkSeconds? = [fastTranscriptCoverageEndSec, finalReach]
            .compactMap { $0 }
            .filter { $0.isFinite }
            .max()
        guard let transcriptReach else { return false }
        // R4 review: through ``WatermarkSeconds/reaches(past:byMoreThan:)``.
        // Written in raw values the guard did not enforce the paragraph above —
        // probe PA3 substituted `adScanCoveredSec.rawValue` for the reach and it
        // COMPILED. Rail TY23.
        return transcriptReach.reaches(past: episodeDurationSec, byMoreThan: tolerance)
    }

    /// playhead-x0lb: the episode's transcript DENSITY — deliberately adjacent
    /// to ``adScanFraction`` so the contrast is unmissable, and typed so the two
    /// cannot be swapped.
    ///
    /// * numerator: ``fastTranscriptCoveredSec`` — the interval-unioned seconds
    ///   of fast transcript actually present.
    /// * denominator: ``episodeDurationSec`` — the same declared duration
    ///   ``adScanFraction`` uses.
    ///
    /// **A high density is not reach.** Measured on the 2026-08-03 device pull:
    /// 4FF3A238 has a fast density of 0.892 and NO coverage-lane scan row at
    /// all, so its ``adScanFraction`` is absent — nine of the twelve assets on
    /// that pull are in the same position. playhead-fil5 R3 computed this
    /// quantity and read it as the other one; nought of twelve assets cleared
    /// the gate and the feature was dead while every test passed.
    var transcriptDensity: DensityRatio? {
        DensityRatio(transcribed: fastTranscriptCoveredSec, ofDeclaredDuration: episodeDurationSec)
    }

    /// playhead-pz32: how far measured coverage may exceed the declared duration
    /// before the two are judged to describe different audio.
    ///
    /// RELATIVE, capped by one shard. An absolute one-shard tolerance is the
    /// obvious choice and is wrong at the short end: 30 s is 0.8% of an hour-long
    /// episode but 67% of a 45-second trailer, so a 45 s episode whose real audio
    /// runs 74 s would pass an absolute check and render a confident ✓ on a
    /// denominator that is 39% short — the exact failure this guard exists to
    /// prevent, merely relocated. 5% absorbs ordinary feed-vs-measured drift at
    /// every scale; the shard cap keeps long episodes from acquiring a large
    /// absolute allowance (mirroring
    /// ``FastTranscriptCoverageInvariant/Tolerances/watermarkPastDurationSec``).
    static func adScanDurationToleranceSec(episodeDurationSec: EpisodeSeconds) -> Double {
        min(AnalysisAudioService.defaultShardDuration, 0.05 * episodeDurationSec.rawValue)
    }
}

/// playhead-hygc.1.2: shared arithmetic for ``AnalysisCoverageSummary``.
/// Pure value-type math so unit tests can hit it directly without touching
/// SQLite.
enum AnalysisCoverageMath {

    /// Compute the unioned (de-overlapped) seconds covered by a sequence
    /// of half-open intervals `[start, end)`. Inputs may be in any order;
    /// degenerate intervals (`end <= start`) contribute zero. Overlapping
    /// or touching intervals collapse before the seconds total is taken,
    /// so a value greater than the sum of widths is impossible.
    static func unionedSeconds(_ intervals: [(start: Double, end: Double)]) -> Double {
        guard !intervals.isEmpty else { return 0 }
        // Filter out degenerate pairs up front so the merge loop only has
        // to deal with valid intervals. `isFinite` excludes both `NaN`
        // (so the total never becomes NaN) AND ±Infinity (so the total
        // never becomes Infinity from a single poisoned endpoint).
        // Production data is real audio timestamps so non-finite values
        // shouldn't arrive here, but the helper is reachable
        // independently of the SQL filter, so make the contract explicit.
        let valid = intervals.filter {
            $0.start.isFinite && $0.end.isFinite && $0.end > $0.start
        }
        guard !valid.isEmpty else { return 0 }
        let sorted = valid.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start < rhs.start }
            return lhs.end < rhs.end
        }
        var total: Double = 0
        var currentStart = sorted[0].start
        var currentEnd = sorted[0].end
        for i in 1..<sorted.count {
            let interval = sorted[i]
            if interval.start <= currentEnd {
                // Overlap or touch — extend the current run if it grows.
                currentEnd = max(currentEnd, interval.end)
            } else {
                // Disjoint — close the current run and start a new one.
                total += currentEnd - currentStart
                currentStart = interval.start
                currentEnd = interval.end
            }
        }
        total += currentEnd - currentStart
        return total
    }

    /// playhead-sd71: gap-aware analyzed-coverage AREA. Clips each interval
    /// to the closed window `[0, upperBound]` and returns the unioned
    /// seconds of what remains — "of these intervals, how many de-overlapped
    /// seconds fall at or before `upperBound` (and at or after zero)?".
    ///
    /// The load-bearing property: the result is always
    /// `<= unionedSeconds(intervals)` for the same input, because every
    /// clipped interval `[max(0, s), min(e, upperBound)]` is a subset of its
    /// source `[s, e]`. Callers pass the transcript intervals and the
    /// analysis frontier (watermark) so the AN pipeline metric measures the
    /// analyzed AREA — a subset of the transcript union — and can never
    /// exceed TX, unlike the raw frontier watermark which overshoots a
    /// gappy transcript.
    ///
    /// Bounds handling mirrors ``unionedSeconds(_:)``'s finiteness contract:
    /// non-finite interval endpoints are dropped. `upperBound <= 0` clips
    /// everything away → `0`. A `+Infinity` `upperBound` means "no upper
    /// clip" and returns the full ``unionedSeconds(_:)``; a `NaN` or
    /// `-Infinity` `upperBound` is not a usable frontier → `0`.
    static func unionedSecondsClipped(
        _ intervals: [(start: Double, end: Double)],
        upperBound: Double
    ) -> Double {
        guard upperBound.isFinite else {
            return upperBound == .infinity ? unionedSeconds(intervals) : 0
        }
        guard upperBound > 0 else { return 0 }
        return unionedSeconds(clip(intervals, to: upperBound))
    }

    /// playhead-pz32: unioned seconds of `intervals` that ALSO fall inside
    /// `bounds` — the de-overlapped intersection area of two interval sets.
    ///
    /// Used to intersect semantic-scan window spans with the fast-transcript
    /// union. A scan window's persisted `[windowStartTime, windowEndTime]` is
    /// `first.startTime ... last.endTime` over the segments that fit one prompt
    /// (`FoundationModelClassifier.planPassA`), so when the transcript has a
    /// hole between two consecutive segments the window's BOUNDS straddle audio
    /// whose text never entered the prompt. Taking the bounds at face value
    /// would report a gappy transcript as fully screened — the same
    /// reach-vs-area conflation playhead-sd71 removed one layer up. You cannot
    /// read audio you never transcribed, so the intersection is the honest area.
    ///
    /// Result properties, both load-bearing: it is `<=
    /// unionedSeconds(intervals)` AND `<= unionedSeconds(bounds)`, since the
    /// intersection is a subset of each. Non-finite and degenerate intervals are
    /// dropped on both sides; empty `bounds` yields `0` (no transcript evidence
    /// ⇒ nothing can have been read).
    static func unionedSecondsIntersecting(
        _ intervals: [(start: Double, end: Double)],
        within bounds: [(start: Double, end: Double)]
    ) -> Double {
        let left = mergedIntervals(normalize(intervals))
        let right = mergedIntervals(normalize(bounds))
        guard !left.isEmpty, !right.isEmpty else { return 0 }
        var total: Double = 0
        var i = 0
        var j = 0
        // Both sides are disjoint and ascending, so one linear sweep suffices:
        // emit the overlap of the current pair, then advance whichever ends
        // first (it cannot overlap anything later on the other side).
        while i < left.count, j < right.count {
            let start = max(left[i].start, right[j].start)
            let end = min(left[i].end, right[j].end)
            if end > start { total += end - start }
            if left[i].end < right[j].end { i += 1 } else { j += 1 }
        }
        return total
    }

    /// Drop non-finite / degenerate intervals. Shared by the clipping and
    /// intersection helpers so both honour ``unionedSeconds(_:)``'s contract.
    private static func normalize(
        _ intervals: [(start: Double, end: Double)]
    ) -> [(start: Double, end: Double)] {
        intervals.filter { $0.start.isFinite && $0.end.isFinite && $0.end > $0.start }
    }

    /// playhead-wogi / playhead-dgly: the largest PREFIX of an episode that a set
    /// of EXAMINED scan windows actually supports — "how far from zero did
    /// scanning get before it hit a hole wide enough to be worth re-scanning?".
    ///
    /// * numerator / denominator: none — a position.
    /// * unit: seconds of episode audio, measured FROM ZERO.
    ///
    /// **What it reads when the thing it measures never happened.** Zero. An
    /// asset with no examined window has no supported prefix at all, and one
    /// whose first examined window starts beyond `rescanThreshold` from the head
    /// also reads zero — the walk never gets going, which is the honest answer
    /// for a cursor that claims `[0, x]`.
    ///
    /// **ONE RULER, TWO READERS.** This is the walk `playhead-wogi`'s V51
    /// migration used to lower an over-claimed coarse cursor; it is lifted here
    /// so ``PersistedStateInvariantEvaluator`` can ask the same question without
    /// writing a second expression of it. Two expressions of one quantity that
    /// happen to agree is exactly how the certainty tier and its consumers came
    /// apart (playhead-6qvf), and it is what this programme exists to remove.
    ///
    /// **NOT interchangeable with
    /// ``BackfillJobRunner/contiguousPlannedReach(spans:rescanThreshold:)``, and
    /// the difference is the SEED rather than the rule.** That one measures from
    /// the FIRST span it was handed, because a resume legitimately begins
    /// mid-episode and measuring from zero would return `nil` for every one of
    /// them. This one measures from ZERO because its question is what an
    /// ``EpisodeSeconds`` cursor is entitled to claim, and that claim is
    /// `[0, x]`.
    static func supportedScannedPrefix(
        examinedSpans: [(start: Double, end: Double)],
        rescanThreshold: RescanThresholdSec
    ) -> EpisodeSeconds {
        var reach = 0.0
        for span in normalize(examinedSpans).sorted(by: { $0.start < $1.start }) {
            if rescanThreshold.warrantsRescan(gapSec: span.start - reach) { break }
            reach = max(reach, span.end)
        }
        return EpisodeSeconds(reach)
    }

    /// playhead-pz32: the widest untranscribed gap that may be BRIDGED when
    /// measuring semantic ad-scan area — see ``bridgingShortGaps(_:upTo:)``.
    ///
    /// Chosen for a PROVABLE property, not fitted to a corpus: 5 s is the
    /// smallest minimum-ad-width any detection lane uses
    /// (`RediffDiffer.minGapFps(minAdSeconds:)` and
    /// `RediffSlotOwnership.Config.minAdSeconds` both default to `5.0`; the
    /// segment aggregator's floor is 30 s, six times larger). A bridged gap is
    /// therefore always shorter than the shortest span this app will ever call
    /// an ad, so bridging cannot conceal one.
    /// playhead-x0lb: a ``BridgeToleranceSec``, not a bare `Double`, so it
    /// cannot be interchanged with ``RescanThresholdSec/adScanRescanWorthyGapSec``
    /// (60 s, playhead-a1x0) — two gap widths in seconds answering opposite
    /// questions, which Dan called out on a1x0 as instance 19 pre-loaded.
    static let adScanBridgeableGapSec = BridgeToleranceSec(5.0)

    /// playhead-pz32: coalesce intervals across gaps no wider than `maxGapSec`,
    /// returning a disjoint ascending set.
    ///
    /// Why the ad-scan measure needs this. A `transcript_chunks` row spans the
    /// FIRST WORD's start to the LAST WORD's end, so every inter-utterance
    /// breath is a hole in the raw chunk union — measured on the 2026-04-25
    /// device capture, `union(chunks) / transcriptSpan` is 0.68–0.976 across
    /// five assets with 182–1,199 disjoint runs each, and the largest gap in
    /// three of them is under 9 s. Intersecting scan windows with the RAW union
    /// therefore caps the ad-scan fraction below the 0.98 readiness threshold on
    /// every real episode, which would make the ✓ unreachable — an under-claim so
    /// total it deletes the signal instead of correcting it.
    ///
    /// Bridging sub-ad-width gaps measures what the scan actually did: a window's
    /// prompt is a contiguous run of transcript, and a half-second pause inside
    /// it was read. What must NOT be bridged is a genuine untranscribed BLOCK — a
    /// music bed or outro no pass ever read. On the same capture those are
    /// unmistakable (single gaps of 90 s and 1,050 s), and at a 5 s bridge they
    /// remain holes: those two assets stay at 0.96 and 0.71 (correctly not
    /// ready) while the three well-transcribed ones reach 0.983–1.0.
    static func bridgingShortGaps(
        _ intervals: [(start: Double, end: Double)],
        upTo maxGapSec: BridgeToleranceSec
    ) -> [(start: Double, end: Double)] {
        mergedIntervals(normalize(intervals), bridging: max(0, maxGapSec.rawValue))
    }

    /// Sort + coalesce ALREADY-NORMALIZED intervals into a disjoint ascending
    /// union. Touching intervals collapse, matching ``unionedSeconds(_:)``.
    /// `bridging` additionally coalesces across gaps no wider than itself.
    private static func mergedIntervals(
        _ intervals: [(start: Double, end: Double)],
        bridging: Double = 0
    ) -> [(start: Double, end: Double)] {
        let sorted = intervals.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start < rhs.start }
            return lhs.end < rhs.end
        }
        var merged: [(start: Double, end: Double)] = []
        for interval in sorted {
            guard let last = merged.last else {
                merged.append(interval)
                continue
            }
            if interval.start <= last.end + bridging {
                merged[merged.count - 1] = (start: last.start, end: max(last.end, interval.end))
            } else {
                merged.append(interval)
            }
        }
        return merged
    }

    /// Clip every interval to `[0, upperBound]`, dropping non-finite /
    /// degenerate ones FIRST so a poisoned endpoint cannot survive as a
    /// synthetic `[0, upperBound]` span after the `max`/`min`.
    private static func clip(
        _ intervals: [(start: Double, end: Double)],
        to upperBound: Double
    ) -> [(start: Double, end: Double)] {
        normalize(intervals).compactMap { interval -> (start: Double, end: Double)? in
            let start = max(0, interval.start)
            let end = min(interval.end, upperBound)
            guard end > start else { return nil }
            return (start: start, end: end)
        }
    }
}

/// playhead-0sro: the persisted-state invariant for the fast-transcript
/// coverage watermark (`analysis_assets.fastTranscriptCoverageEndTime`).
///
/// The watermark is a HIGH-WATER REACH: "how far into the audio has the
/// fast pass reached?". `transcript_chunks` rows with `pass = 'fast'` are
/// the canonical record of that reach, so the watermark must never sit
/// behind their `MAX(endTime)`, and it must never claim reach past the
/// end of the audio. Those are the two directions this invariant checks.
///
/// Why an explicit tolerance rather than exact equality:
///   - **Behind chunks.** Shard ends and chunk ends are floating-point
///     seconds derived from different arithmetic (sample-count division
///     vs. ASR segment timestamps), so a sub-second disagreement is
///     normal and is NOT a defect. Only a gap wider than
///     ``Tolerances/watermarkBehindChunksSec`` means the watermark
///     genuinely lags the transcript (the playhead-0sro bug: 60 s
///     persisted against 3575.88 s of real chunk coverage).
///   - **Past duration.** `episodeDurationSec` is the shard-sum of the
///     decoded audio (or a probe), while the final shard's end is the
///     sum of shard durations — and a feed-declared duration can differ
///     from the measured file by whole seconds. The final fast chunk can
///     also legitimately end a hair past the shard-sum. So a watermark
///     within ``Tolerances/watermarkPastDurationSec`` of the duration is
///     healthy; beyond that the watermark is describing audio that does
///     not exist.
///
/// This invariant deliberately says NOTHING about interior gaps. A
/// watermark of 3575 s over a transcript with a hole at 1000–1200 s is
/// *correct* — reach is not area. Gap-aware AREA is
/// ``AnalysisCoverageSummary/fastTranscriptCoveredSec`` (interval union),
/// and conflating the two is the "AN 100% / TX 39%" antipattern
/// playhead-sd71 fixed. Keep them separate.
enum FastTranscriptCoverageInvariant {

    /// Tolerated slack in each direction, in seconds. Both default to a
    /// deliberately explicit value rather than 0 — see the type doc for
    /// why exact equality is the wrong contract.
    struct Tolerances: Sendable, Equatable {
        /// How far the watermark may sit BELOW the canonical chunk
        /// `MAX(endTime)` before it counts as stale. One second absorbs
        /// float/timestamp disagreement without hiding a real lag.
        var watermarkBehindChunksSec: Double
        /// How far the watermark may sit ABOVE `episodeDurationSec`
        /// before it counts as over-claiming. One shard (30 s) absorbs
        /// feed-vs-measured duration drift and shard-sum rounding.
        var watermarkPastDurationSec: Double

        init(
            watermarkBehindChunksSec: Double = 1.0,
            watermarkPastDurationSec: Double = AnalysisAudioService.defaultShardDuration
        ) {
            self.watermarkBehindChunksSec = watermarkBehindChunksSec
            self.watermarkPastDurationSec = watermarkPastDurationSec
        }

        static let standard = Tolerances()
    }

    /// A specific way the persisted watermark contradicts the artifacts
    /// around it. Carries the measured numbers so callers can log a
    /// diagnosable line without a second query.
    enum Violation: Sendable, Equatable {
        /// The watermark lags canonical fast-chunk coverage by more than
        /// ``Tolerances/watermarkBehindChunksSec``. This is the
        /// playhead-0sro stale-watermark defect.
        case watermarkBehindChunks(watermarkSec: Double, chunkMaxEndSec: Double)
        /// The watermark claims reach past the end of the audio by more
        /// than ``Tolerances/watermarkPastDurationSec``.
        case watermarkPastDuration(watermarkSec: Double, episodeDurationSec: Double)
    }

    /// Evaluate the invariant for one asset.
    ///
    /// - Parameters:
    ///   - watermarkSec: persisted `fastTranscriptCoverageEndTime`. `nil`
    ///     (never written) is vacuously healthy — there is nothing to
    ///     contradict yet; the caller distinguishes "absent" from "stale"
    ///     via provenance, not via this invariant.
    ///   - chunkMaxEndSec: `MAX(endTime)` over `pass = 'fast'` chunks, or
    ///     `nil` when no fast chunks have landed.
    ///   - episodeDurationSec: canonical duration, or `nil`/non-positive
    ///     when unknown (the past-duration check is then skipped rather
    ///     than reported against a bogus denominator).
    /// - Returns: every violation found, in a stable order. Empty means
    ///   the persisted state is self-consistent.
    static func violations(
        watermarkSec: Double?,
        chunkMaxEndSec: Double?,
        episodeDurationSec: Double?,
        tolerances: Tolerances = .standard
    ) -> [Violation] {
        // A watermark that was never written cannot contradict anything.
        // Non-finite input is treated the same way: there is no
        // meaningful comparison to make, and reporting a violation on
        // NaN would produce an unactionable log line.
        guard let watermarkSec, watermarkSec.isFinite else { return [] }

        var found: [Violation] = []

        if let chunkMaxEndSec,
           chunkMaxEndSec.isFinite,
           chunkMaxEndSec - watermarkSec > tolerances.watermarkBehindChunksSec {
            found.append(
                .watermarkBehindChunks(
                    watermarkSec: watermarkSec,
                    chunkMaxEndSec: chunkMaxEndSec
                )
            )
        }

        if let episodeDurationSec,
           episodeDurationSec.isFinite,
           episodeDurationSec > 0,
           watermarkSec - episodeDurationSec > tolerances.watermarkPastDurationSec {
            found.append(
                .watermarkPastDuration(
                    watermarkSec: watermarkSec,
                    episodeDurationSec: episodeDurationSec
                )
            )
        }

        return found
    }

    /// Convenience predicate: `true` when the persisted state satisfies
    /// the invariant under `tolerances`.
    static func holds(
        watermarkSec: Double?,
        chunkMaxEndSec: Double?,
        episodeDurationSec: Double?,
        tolerances: Tolerances = .standard
    ) -> Bool {
        violations(
            watermarkSec: watermarkSec,
            chunkMaxEndSec: chunkMaxEndSec,
            episodeDurationSec: episodeDurationSec,
            tolerances: tolerances
        ).isEmpty
    }
}

struct PodcastProfile: Sendable {
    let podcastId: String
    let sponsorLexicon: String?
    let normalizedAdSlotPriors: String?
    let repeatedCTAFragments: String?
    let jingleFingerprints: String?
    let implicitFalsePositiveCount: Int
    let skipTrustScore: Double
    let observationCount: Int
    let mode: String
    let recentFalseSkipSignals: Int
    /// ef2.5.1: JSON-encoded `ShowTraitProfile`. `nil` until first episode
    /// observation populates the profile. Decoded lazily by consumers.
    let traitProfileJSON: String?
    /// playhead-i9dj: human-readable show title (e.g. "Diary of a CEO").
    /// `nil` on pre-i9dj rows that have not been touched, and on the
    /// transient profile values that bounce through trust-scoring rebuilds
    /// without the title in scope. Defaults to `nil` so:
    ///   * existing PodcastProfile constructors compile unchanged,
    ///   * trust-scoring rebuilds that pass `title: nil` do NOT clobber
    ///     a previously-persisted title — `upsertProfile` uses
    ///     `COALESCE(excluded.title, podcast_profiles.title)` to preserve
    ///     the existing column value when the new write is `nil`.
    /// Populated via the dedicated
    /// ``AnalysisStore/updateProfileTitle(podcastId:title:)`` setter from
    /// the call site that owns the SwiftData `Podcast`.
    let title: String?
    /// playhead-084j: JSON-encoded `AdDurationStats` aggregate of confirmed
    /// ad-window durations observed for this show. Drives the show-local
    /// override in `PriorHierarchyResolver`.
    ///
    /// `nil` on pre-084j rows that have not been touched, and on
    /// transient profile values that bounce through other rebuild paths
    /// without the stats in scope. `upsertProfile` uses
    /// `COALESCE(excluded.adDurationStatsJSON, podcast_profiles.adDurationStatsJSON)`
    /// so a `nil` write never clobbers persisted observations.
    let adDurationStatsJSON: String?
    /// playhead-spxs: derived `NetworkIdentity.networkId` for this show
    /// — the lowercase grouping key produced by
    /// `NetworkIdentityExtractor`. `nil` until the next feed-metadata
    /// pass populates it (or for shows whose RSS metadata yields no
    /// usable network signal). Used by
    /// `AnalysisStore.fetchProfiles(forNetworkId:)` to find sibling
    /// shows so `NetworkPriorsBuilder` can roll up cross-show
    /// `adDurationStatsJSON` aggregates into a `NetworkPriors`. The
    /// resolver consumes that aggregate as the level-1 (network) tier
    /// of the 4-level prior hierarchy. Carries COALESCE-preserve
    /// semantics in `upsertProfile` so a profile rebuild that doesn't
    /// know the network (trust-scoring, etc.) does NOT clobber the
    /// previously-recorded value.
    let networkId: String?
    /// playhead-xsdz.71 (Signal 1): the identified DAI-stitch network's
    /// `DAIStitchNetwork.rawValue`, derived from the enclosure download's
    /// redirect chain by `DAIStitchClassifier` (a DISTINCT classifier from the
    /// editorial `networkId` above). `nil` until the first redirect chain is
    /// observed for the show (and on pre-xsdz.71 rows). Written ONLY by the
    /// column-specific `updateProfileDAIStitch` setter (never by
    /// `upsertProfile`), so a profile rebuild preserves it. ADDITIVE-ONLY —
    /// recorded but not yet consumed.
    let daiStitchNetwork: String?
    /// playhead-xsdz.71 (Signal 1): whether DAI is EXPECTED for the show (a
    /// known DAI-stitch host appeared in the redirect chain). `nil` until
    /// classified; set together with `daiStitchNetwork`.
    let daiExpected: Bool?
    /// playhead-gard: JSON-encoded `DetectorTrustLedger` — per-DETECTOR-CLASS
    /// trust state for this show, replacing the single `skipTrustScore` /
    /// `mode` / `recentFalseSkipSignals` triple as the policy input.
    ///
    /// `nil` on every pre-gard row and on any show that has not yet diverged
    /// from the legacy scalar. NULL is not a gap: `DetectorTrustLedger.seed`
    /// derives each show-governed class's state from the legacy columns, so an
    /// untouched row keeps exactly the posture it had.
    ///
    /// The legacy columns are STILL WRITTEN, unchanged, by every path that
    /// wrote them before. A binary that predates this column never selects it
    /// and reads the legacy scalar — the safe-degradation half of the
    /// playhead-6qvf pattern. Carries COALESCE-preserve semantics in
    /// `upsertProfile` so a profile rebuild that does not know the ledger
    /// (priors update, title write) cannot clobber it.
    let detectorTrustJSON: String?

    init(
        podcastId: String,
        sponsorLexicon: String?,
        normalizedAdSlotPriors: String?,
        repeatedCTAFragments: String?,
        jingleFingerprints: String?,
        implicitFalsePositiveCount: Int,
        skipTrustScore: Double,
        observationCount: Int,
        mode: String,
        recentFalseSkipSignals: Int,
        traitProfileJSON: String? = nil,
        title: String? = nil,
        adDurationStatsJSON: String? = nil,
        networkId: String? = nil,
        daiStitchNetwork: String? = nil,
        daiExpected: Bool? = nil,
        detectorTrustJSON: String? = nil
    ) {
        self.podcastId = podcastId
        self.sponsorLexicon = sponsorLexicon
        self.normalizedAdSlotPriors = normalizedAdSlotPriors
        self.repeatedCTAFragments = repeatedCTAFragments
        self.jingleFingerprints = jingleFingerprints
        self.implicitFalsePositiveCount = implicitFalsePositiveCount
        self.skipTrustScore = skipTrustScore
        self.observationCount = observationCount
        self.mode = mode
        self.recentFalseSkipSignals = recentFalseSkipSignals
        self.traitProfileJSON = traitProfileJSON
        self.title = title
        self.adDurationStatsJSON = adDurationStatsJSON
        self.networkId = networkId
        self.daiStitchNetwork = daiStitchNetwork
        self.daiExpected = daiExpected
        self.detectorTrustJSON = detectorTrustJSON
    }

    /// playhead-gard: the decoded per-detector ledger. An absent or corrupt
    /// column yields an EMPTY ledger, under which every class falls back to the
    /// legacy-scalar seed — history is lost, posture is not.
    var detectorTrustLedger: DetectorTrustLedger {
        DetectorTrustLedger.decode(detectorTrustJSON)
    }

    /// Convenience: decode the stored trait profile, falling back to
    /// `ShowTraitProfile.unknown` when absent or corrupt.
    var traitProfile: ShowTraitProfile {
        guard let json = traitProfileJSON,
              let data = json.data(using: .utf8),
              let decoded = try? JSONDecoder().decode(ShowTraitProfile.self, from: data)
        else { return .unknown }
        return decoded
    }

    /// playhead-xsdz.71 (Signal 1): the persisted DAI-stitch classification for
    /// this show, or `nil` when no redirect chain has been observed yet. The
    /// read accessor for the recorded DAI-EXPECTED prior. `matchedHost` is a
    /// diagnostics-only field that is not persisted, so it reads back as `nil`.
    var daiStitchClassification: DAIStitchClassification? {
        guard let raw = daiStitchNetwork,
              let network = DAIStitchNetwork(rawValue: raw) else { return nil }
        return DAIStitchClassification(
            stitchNetwork: network,
            daiExpected: daiExpected ?? false,
            matchedHost: nil
        )
    }
}

/// bd-m8k: Per-podcast CoveragePlanner state. Sibling row to
/// `PodcastProfile`; persisted in the `podcast_planner_state` table that the
/// v4 migration creates. Rows are upserted lazily on first observation, never
/// backfilled. `recallSamples` is the most-recent-up-to-3 ring of full-
/// rescan **recall** measurements (oldest first); the cached
/// `stableRecallFlag` reflects the result of evaluating both the episode-
/// count floor and the recall threshold against this ring at the moment
/// of the last write.
///
/// Cycle 2 C4: the metric was historically misnamed "precision" — it is
/// actually recall (covered / actual ad line refs). The struct fields use
/// the corrected name; the persisted SQLite columns and JSON keys keep the
/// legacy `precision*` names so existing v4 rows decode without a
/// migration. Each storage boundary is annotated with
/// `// historical: stored as "precision"; semantically recall`.
struct PodcastPlannerState: Sendable, Equatable {
    let podcastId: String
    let observedEpisodeCount: Int
    let episodesSinceLastFullRescan: Int
    /// Cycle 2 C4: stored as `stablePrecisionFlag` in SQLite; semantically
    /// the stable-recall flag. See type-level doc.
    let stableRecallFlag: Bool
    let lastFullRescanAt: Double?
    /// Most recent up to `AnalysisStore.plannerRecallRingSize` full-rescan
    /// recall samples. Oldest first; new samples are appended and the
    /// oldest dropped on overflow.
    /// Cycle 2 C4: stored across `precisionSample1..3` columns; semantically
    /// recall. See type-level doc.
    let recallSamples: [Double]
    /// Cycle 4 B4: per-podcast running total of episodes observed that
    /// produced no recall sample (ad-free full rescans). Persisted on
    /// `podcast_planner_state` so the counter accrues across
    /// `BackfillJobRunner` instances and across process restarts — the
    /// runner-level counter of the same name is per-run only and was
    /// therefore always 0 or 1 when read. Legacy rows that predate this
    /// column decode as 0.
    let episodesObservedWithoutSampleCount: Int
    /// Cycle 4 B4: per-podcast running total of episodes where every
    /// non-fullEpisodeScan narrowing phase returned `wasEmpty == true`.
    /// Increments fire on BOTH full rescans and live targeted-with-audit
    /// runs, so the counter captures the cross-phase empty signal that
    /// individual `narrowing.empty.{phase}` cannot. Legacy rows decode
    /// as 0.
    let narrowingAllPhasesEmptyEpisodeCount: Int
}

struct PreviewBudget: Sendable {
    let canonicalEpisodeKey: String
    let consumedAnalysisSeconds: Double
    let graceBreakWindow: Double
    let lastUpdated: Double
}

/// playhead-uzdq: minimal return value from
/// ``AnalysisStore/acquireEpisodeLease``. The store side doesn't carry
/// preemption signals or in-memory checkpoint caches — those live on
/// the coordinator's richer ``EpisodeExecutionLease`` struct. This
/// descriptor just plumbs the persisted state back to the caller.
struct EpisodeExecutionLeaseDescriptor: Sendable, Equatable {
    let jobId: String
    let episodeId: String
    let ownerWorkerId: String
    let generationID: String
    let schedulerEpoch: Int
    let acquiredAt: Double
    let expiresAt: Double
}

struct AnalysisJob: Sendable {
    let jobId: String
    let jobType: String         // "preAnalysis" | "playback" | "backfill"
    let episodeId: String
    let podcastId: String?
    let analysisAssetId: String?
    let workKey: String         // fingerprint + analysisVersion + jobType
    let sourceFingerprint: String
    let downloadId: String
    let priority: Int
    let desiredCoverageSec: Double
    let featureCoverageSec: Double
    let transcriptCoverageSec: Double
    let cueCoverageSec: Double
    let state: String
    let attemptCount: Int
    let nextEligibleAt: Double?
    let leaseOwner: String?
    let leaseExpiresAt: Double?
    let lastErrorCode: String?
    let createdAt: Double
    let updatedAt: Double
    /// playhead-uzdq: generation ID owned by the current lease holder,
    /// or `""` when no lease has ever been acquired. Stored as
    /// `generationID TEXT NOT NULL DEFAULT ''` and read back as the
    /// empty string for pre-uzdq rows. Callers that need a typed
    /// identity use ``EpisodeExecutionLease/generationID`` (UUID).
    let generationID: String
    /// playhead-uzdq: scheduler epoch captured when the current lease
    /// holder acquired the row, or `0` when no lease has ever been
    /// acquired.
    let schedulerEpoch: Int
    /// playhead-bnrs: primary artifact class this job will write to.
    /// In-memory only (NOT persisted in `analysis_jobs`); consumed by
    /// `AdmissionGate` at admission time. Defaults to `.media` so every
    /// existing call-site compiles unchanged — media is the dominant
    /// write class for pre-analysis jobs.
    let artifactClass: ArtifactClass
    /// playhead-bnrs: caller-estimated write bytes for the next slice
    /// this job will emit. In-memory only (NOT persisted); consumed by
    /// `AdmissionGate` as a headroom input for per-class storage slice
    /// sizing. Defaults to `0` so existing call-sites compile unchanged;
    /// downstream beads that care about precise sizing can set this
    /// explicitly at enqueue time.
    let estimatedWriteBytes: Int64

    // Existing-style memberwise init that defaults the uzdq fields so
    // every call-site in the codebase compiles unchanged. New callers
    // pass the two uzdq fields explicitly. The playhead-bnrs fields
    // (`artifactClass`, `estimatedWriteBytes`) follow the same defaulted
    // pattern so the admission-gate integration adds no call-site churn.
    init(
        jobId: String,
        jobType: String,
        episodeId: String,
        podcastId: String?,
        analysisAssetId: String?,
        workKey: String,
        sourceFingerprint: String,
        downloadId: String,
        priority: Int,
        desiredCoverageSec: Double,
        featureCoverageSec: Double,
        transcriptCoverageSec: Double,
        cueCoverageSec: Double,
        state: String,
        attemptCount: Int,
        nextEligibleAt: Double?,
        leaseOwner: String?,
        leaseExpiresAt: Double?,
        lastErrorCode: String?,
        createdAt: Double,
        updatedAt: Double,
        generationID: String = "",
        schedulerEpoch: Int = 0,
        artifactClass: ArtifactClass = .media,
        estimatedWriteBytes: Int64 = 0
    ) {
        self.jobId = jobId
        self.jobType = jobType
        self.episodeId = episodeId
        self.podcastId = podcastId
        self.analysisAssetId = analysisAssetId
        self.workKey = workKey
        self.sourceFingerprint = sourceFingerprint
        self.downloadId = downloadId
        self.priority = priority
        self.desiredCoverageSec = desiredCoverageSec
        self.featureCoverageSec = featureCoverageSec
        self.transcriptCoverageSec = transcriptCoverageSec
        self.cueCoverageSec = cueCoverageSec
        self.state = state
        self.attemptCount = attemptCount
        self.nextEligibleAt = nextEligibleAt
        self.leaseOwner = leaseOwner
        self.leaseExpiresAt = leaseExpiresAt
        self.lastErrorCode = lastErrorCode
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.generationID = generationID
        self.schedulerEpoch = schedulerEpoch
        self.artifactClass = artifactClass
        self.estimatedWriteBytes = estimatedWriteBytes
    }

    static func computeWorkKey(fingerprint: String, analysisVersion: Int, jobType: String) -> String {
        "\(fingerprint):\(analysisVersion):\(jobType)"
    }
}

// MARK: - Store errors

enum AnalysisStoreError: Error, CustomStringConvertible, Equatable {
    case openFailed(code: Int32, message: String)
    case migrationFailed(String)
    case queryFailed(String)
    case insertFailed(String)
    case notFound
    case duplicateJobId(String)
    case invalidRow(column: Int)
    case invalidEvidenceEvent(String)
    case invalidScanCohortJSON(String)
    /// A hot-path reconciliation observed one producer revision, suspended,
    /// then found different same-ID material when its transaction began.
    /// Rejecting the whole transaction prevents stale updates/retirements from
    /// mutating the replacement.
    case staleAdWindowRevision(id: String)
    /// C-2: raised when a backfill-job state transition is attempted against
    /// a row whose current status does not permit it (e.g. transitioning a
    /// `.complete` or `.failed` row back into `.running`).
    ///
    /// Fix #6: `fromStatus` carries the row's prior status at the moment
    /// the transition was rejected. It is `nil` when no row existed for
    /// the `jobId`, so callers can distinguish "missing" from "in a
    /// specific terminal state" without re-querying.
    case invalidStateTransition(jobId: String, fromStatus: String?, toStatus: String)
    /// H-2: raised when `insertEvidenceEvent` encounters a PRIMARY KEY
    /// collision where the existing row's body (evidenceJSON/createdAt)
    /// differs from the incoming row. The M-4 INSERT OR IGNORE path was
    /// silently preserving the stored body; callers that truly collide on
    /// id but with different content now get a loud failure.
    case evidenceEventBodyMismatch(id: String)
    /// playhead-4my.10.1 (L5): a JSON encoder produced bytes we could not
    /// decode. Foundation's `JSONEncoder` should never produce non-UTF8
    /// output, so this is structural — we surface it instead of
    /// fall-through-defaulting the persisted column to `"[]"` (which
    /// would silently mask future regressions).
    case encodingFailure(String)

    var description: String {
        switch self {
        case .openFailed(let code, let msg): "SQLite open failed (\(code)): \(msg)"
        case .migrationFailed(let msg): "Migration failed: \(msg)"
        case .queryFailed(let msg): "Query failed: \(msg)"
        case .insertFailed(let msg): "Insert failed: \(msg)"
        case .notFound: "Row not found"
        case .duplicateJobId(let id): "Duplicate backfill job id: \(id)"
        case .invalidRow(let col): "Unexpected NULL in non-null column \(col)"
        case .invalidEvidenceEvent(let msg): "Invalid evidence event: \(msg)"
        case .invalidScanCohortJSON(let msg): "Invalid scanCohortJSON: \(msg)"
        case .staleAdWindowRevision(let id):
            "Stale ad-window producer revision: \(id)"
        case .invalidStateTransition(let id, let from, let to):
            "Invalid backfill job state transition for \(id): \(from ?? "<missing>") -> \(to)"
        case .evidenceEventBodyMismatch(let id):
            "Evidence event id '\(id)' already persisted with a different body"
        case .encodingFailure(let msg):
            "Encoding failure: \(msg)"
        }
    }
}

/// playhead-q45f.1: one persisted listen-rewind event. Each row records a
/// single user tap on the "Listen" button of an auto-skipped ad window.
/// `time` is the episode-time the user was returned to (the snapped start
/// of the skipped span, mirroring `seek(to: item.adStartTime)` in
/// `NowPlayingViewModel.handleListenRewind`); `createdAt` is wall-clock
/// UNIX seconds for ordering and stale-row pruning.
struct AdListenRewindRow: Sendable, Hashable {
    let analysisAssetId: String
    let windowId: String
    let podcastId: String
    let time: Double
    let createdAt: Date

    init(
        analysisAssetId: String,
        windowId: String,
        podcastId: String,
        time: Double,
        createdAt: Date
    ) {
        self.analysisAssetId = analysisAssetId
        self.windowId = windowId
        self.podcastId = podcastId
        self.time = time
        self.createdAt = createdAt
    }
}

// MARK: - AnalysisStore actor

// MARK: - Duplicate placeholder-asset reconciliation (playhead-0hi9 part 3)

/// What one ``AnalysisStore/reconcileDuplicatePlaceholderAssets()`` pass did.
/// Counts are cumulative across every episode inspected in the pass.
struct DuplicateAssetMergeSummary: Sendable, Equatable {
    /// Episodes found holding more than one `analysis_assets` row.
    var episodesInspected = 0
    /// Placeholder rows folded into a canonical row and deleted.
    var placeholdersMerged = 0
    /// Child rows re-pointed from a placeholder to its survivor.
    var childRowsRepointed = 0
    /// Child rows that could NOT be re-pointed because the survivor already
    /// held an equivalent row under a UNIQUE/PRIMARY KEY on the asset column
    /// (`ad_decision_results.analysisAssetId` is `UNIQUE`;
    /// `episode_fingerprints`, `feature_extraction_state`, `episode_summaries`,
    /// `rediff_refetch_state`, `rediff_day_zero_attempts` and
    /// `explicit_feedback_egress_baselines` key on it). Deleted explicitly so
    /// the placeholder can go without an FK violation and without orphans.
    var childRowsDiscarded = 0
    /// Rows that survived a merge, so an async caller can re-probe their
    /// duration and re-score their terminal claim.
    var survivingAssetIds: [String] = []
    /// Survivors whose `episodeDurationSec` was FILLED IN from a folded-in
    /// placeholder because they had none of their own.
    ///
    /// R1: such a value is untrustworthy BY CONSTRUCTION — the placeholder's
    /// duration is the shard sum of an 8 MiB mid-download prefix (part 1 of
    /// this bead), which is why the whole bead exists. The caller's ordinary
    /// "does this duration look wrong" check (`missing, or contradicted by its
    /// own coverage`) cannot see it: a poisoned ~543 s that happens to exceed
    /// the merged coverage watermark looks perfectly plausible and would be
    /// kept forever, because the sweep is one-shot. These ids force a re-probe
    /// against the audio file regardless.
    var survivorsWithInheritedDuration: [String] = []
    /// Completion terminals adopted from a folded-in row.
    var adoptedTerminalStates = 0
    /// Placeholder rows LEFT IN PLACE because their `sourceURL` names a
    /// different artifact than the survivor's. See ``AssetMergeGuard``.
    var skippedDifferentSource = 0
    /// Placeholder rows left in place because one side carried no usable
    /// `sourceURL` at all, so no artifact identity could be compared.
    var skippedUnknownSource = 0
    /// playhead-6av0: duplicate child rows swept AFTER the re-point, for the
    /// tables where `UPDATE OR IGNORE` cannot discard on its own because the
    /// table carries no constraint to conflict on.
    var duplicateChildRowsRemoved = 0
}

/// Whether one placeholder may be folded into one survivor.
///
/// playhead-0hi9: 13 of the 14 duplicated episodes on the owner's device hold
/// two rows naming the SAME file. The 14th holds two DIFFERENT `sourceURL`s.
/// That one is filed separately (playhead-b8hj tracks `sourceURL` storing
/// absolute container paths) and is explicitly out of scope here — but it is
/// in the same table, and this sweep will meet it.
///
/// The merge is irreversible: it re-points child rows and deletes a row. The
/// risk is asymmetric. Skipping a pair leaves the user exactly as broken as
/// before and the sweep can be re-armed later; merging two rows that describe
/// DIFFERENT audio fuses one episode's transcript onto another's analysis and
/// nothing can take that apart afterwards. So the sweep merges only on
/// positive evidence that both rows name the same artifact, and records a
/// reason otherwise.
///
/// The comparison is on the last path component, not the whole URL, precisely
/// because playhead-b8hj makes the leading container path unstable across
/// reinstalls: `DownloadManager.safeFilename(for:)` derives the basename from
/// the episode id, so it survives a container move that rewrites everything to
/// its left. b8hj has since stopped WRITING the volatile prefix (see
/// ``AudioCacheLocation``), which makes this reduction agree with the new
/// `complete/<name>` form as well — but it stays, because the legacy absolute
/// rows it was written for are still in the table and are not being repaired.
enum AssetMergeGuard: Sendable, Equatable {
    /// Both rows name the same on-disk artifact.
    case merge
    /// The rows name different artifacts. Left alone, deliberately.
    case skipDifferentSource(victim: String, survivor: String)
    /// One side has no usable `sourceURL`, so nothing can be compared.
    case skipUnknownSource
}


/// One schema location holding an `analysis_assets.id`, discovered at runtime.
struct ChildAssetColumn: Sendable, Equatable {
    let table: String
    let column: String
}

/// The subset of `analysis_assets` the merge reasons about. Read with an
/// explicit column list rather than `assetSelectColumns` so the merge stays
/// stable as the row type grows fields it has no opinion about.
struct AssetMergeRow: Sendable, Equatable {
    let rowId: Int64
    let id: String
    let assetFingerprint: String
    let createdAt: Double
    let analysisState: String
    let terminalReason: String?
    let sourceURL: String
    /// Declared with a default so the merge's pure helpers can still be
    /// exercised without inventing a duration.
    var episodeDurationSec: Double? = nil

    /// The stable part of `sourceURL`: the hashed filename the download
    /// manager derives from the episode id. `nil` when the value is empty or
    /// carries no path component at all.
    var artifactBasename: String? {
        let trimmed = sourceURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        let component = URL(string: trimmed)?.lastPathComponent
            ?? trimmed.split(separator: "/").last.map(String.init)
        guard let component, !component.isEmpty, component != "/" else { return nil }
        return component.lowercased()
    }

    /// A Pipeline A placeholder writes its own row id into `assetFingerprint`.
    /// That self-reference is the signature: it is exactly what makes the row
    /// unmatchable by every fingerprint-keyed query, and it cannot arise by
    /// accident because every other writer supplies a content hash or a job
    /// fingerprint.
    var isPlaceholder: Bool { assetFingerprint == id }

    var hasCanonicalSHA: Bool {
        CrossUserAnalysisShareKey.isCanonicalFullFileSHA(assetFingerprint)
    }
}

actor AnalysisStore {

    /// Latest persisted schema version. Tests reference this so migration
    /// assertions automatically follow the production constant — hardcoding
    /// the integer in tests has been a recurring source of stale-assertion
    /// flakes whenever the schema bumps.
    nonisolated static let currentSchemaVersion = 61

    /// H1: minimum age (in seconds) a `backfill_jobs` / `final_pass_jobs`
    /// row stuck in `status='running'` must reach before the launch-time
    /// reaper resets it to `queued`. The window must be larger than any
    /// legitimate single in-process work step so a foreground runner
    /// holding a row mid-drain is never racy with a same-process
    /// BGProcessingTask reentry into the reconciler. 10 minutes is well
    /// above the worst observed FM scan duration (sub-second to a few
    /// seconds per window); a stranded row from a crashed prior process
    /// will have an `updatedAt` from before the crash and trivially clear
    /// this floor by the time the next launch fires.
    ///
    /// skeptical-review-cycle-3 M-E: callers that may run for an
    /// indefinite duration (a foreground runner against a degraded device
    /// or large legacy episode) MUST refresh `updatedAt` at intervals
    /// shorter than this floor. `markBackfillJobRunning` and
    /// `markFinalPassJobRunning` both bump `updatedAt` to the current
    /// timestamp on entry, but a job that holds the lease past the floor
    /// without checkpointing risks duplicate-FM-call dispatch when the
    /// reaper flips the row back to `queued`. The runners enforce this
    /// via cooperative checkpoints; long-running shards should call
    /// ``touchBackfillJobLiveness(jobId:)`` on a schedule shorter than this
    /// floor. NOT `markBackfillJobRunning` — since playhead-wxsv that is a
    /// START transition that accepts a `failed` row under the retry budget,
    /// so using it as a heartbeat can resurrect a row the no-progress
    /// watchdog just retired (the exact regression the heartbeat split
    /// exists to prevent; see `touchBackfillJobLiveness`).
    nonisolated static let strandedJobFreshnessSeconds: Int = 600

    /// bd-m8k / Cycle 2 C4: Maximum number of recent full-rescan **recall**
    /// samples retained for the `stable_recall_flag` ring. Must match the
    /// column count in `podcast_planner_state` and the push/shift logic in
    /// `recordPodcastEpisodeObservation`. The persisted columns are still
    /// named `precisionSample{1,2,3}` / `precisionSampleCount`; the
    /// in-memory rename is code-only.
    nonisolated static let plannerRecallRingSize = 3

    /// bd-m8k / Cycle 2 C4: Minimum per-sample recall required for
    /// `stable_recall_flag` to flip true. All samples in the ring must
    /// clear this threshold. The persisted column is still named
    /// `stablePrecisionFlag`; semantically recall.
    nonisolated static let plannerRecallThreshold: Double = 0.85

    /// bd-m8k: Minimum `observed_episode_count` before
    /// `stable_precision_flag` is permitted to be true. Mirrors
    /// `CoveragePlanner.defaultColdStartEpisodeThreshold`.
    nonisolated static let plannerStableObservedEpisodeFloor = 5

    #if DEBUG
    enum FeatureBatchPersistenceFaultInjection: Equatable {
        case afterCoverageUpdateBeforeCommit
    }

    private var featureBatchPersistenceFaultInjection: FeatureBatchPersistenceFaultInjection?

    /// playhead-uhdu (5uvz.1 NIT #1): test-only fault injection points
    /// for `acquireLeaseWithJournal`. Lets tests force the inner journal
    /// append to throw so the rollback contract — phantom-lease impossible
    /// by construction — is validated by execution rather than visual
    /// inspection of the catch block.
    enum LeaseJournalFaultInjection: Equatable {
        /// Throw between the lease UPDATE and the journal append.
        /// Validates that the catch block rolls back the UPDATE so no
        /// phantom-lease (lease held, no journal trail) survives.
        case afterUpdateBeforeJournalAppend
    }

    private var leaseJournalFaultInjection: LeaseJournalFaultInjection?

    /// playhead-8ljj: which coverage-lane CANDIDATE query should throw.
    ///
    /// An `OptionSet` rather than an enum because the two queries fail
    /// INDEPENDENTLY in production — one unreadable population and both are
    /// different findings, and the ledger reason renders them differently
    /// (`unread=resumable` vs `unread=resumable+missingRows`). A seam that
    /// could only express "something failed" could not drive that.
    struct CoarseScanCandidateQueryFaultInjection: OptionSet, Equatable, Sendable {
        let rawValue: Int
        /// `fetchAssetIdsWithResumableBackfillJobs` throws.
        static let resumable = CoarseScanCandidateQueryFaultInjection(rawValue: 1 << 0)
        /// `fetchAssetIdsMissingCoverageLaneJobs` throws.
        static let missingCoverageLaneRows = CoarseScanCandidateQueryFaultInjection(rawValue: 1 << 1)
    }

    private var coarseScanCandidateQueryFaultInjection: CoarseScanCandidateQueryFaultInjection?

    /// playhead-1e86: make ``resetStrandedBackfillJobs()`` throw.
    ///
    /// Deliberately NOT a third case of the OptionSet above: that type is named
    /// for the candidate QUERIES and the reaper is not one of them — it is a
    /// write that runs before them. Folding it in would make the type's name
    /// stop describing its members, which is the spelling half of this repo's
    /// standing defect class.
    private var strandedBackfillSweepFaultInjection = false

    /// playhead-5uvz.3 (Gap-3): test-only fault-injection points for the
    /// `AnalysisWorkScheduler.processJob` outcome arms. The arms now run
    /// inside a single `runSchedulingPass` transaction so progress, the
    /// state-specific writes, and the lease release commit or roll back
    /// together. These checkpoints let tests force a throw between the
    /// individual writes inside that transaction and verify the row's
    /// pre-arm state is preserved (no half-finalized terminal mark).
    enum ProcessJobOutcomeFaultInjection: Equatable {
        /// Throw after the progress UPDATE but before the state UPDATE.
        /// Validates that the progress write rolls back so the row keeps
        /// its previous coverage and is requeued cleanly by orphan recovery.
        case afterProgressUpdateBeforeStateUpdate
        /// Throw after the state UPDATE but before the final lease release.
        /// Validates that the terminal-mark write rolls back so the row
        /// is not stranded with `state=complete` but a still-held lease.
        case afterStateUpdateBeforeLeaseRelease
    }

    private var processJobOutcomeFaultInjection: ProcessJobOutcomeFaultInjection?
    #endif

    /// bd-1tl: dedicated logger for store-level diagnostics that should
    /// reach Console.app on real devices without test scaffolding.
    private let logger = Logger(subsystem: "com.playhead", category: "AnalysisStore")

    /// The raw SQLite handle. Marked `nonisolated(unsafe)` so deinit can close
    /// it without requiring actor isolation (Swift 6 strict concurrency).
    /// All actual usage is funnelled through actor-isolated methods.
    nonisolated(unsafe) private var db: OpaquePointer?

    /// Path to the SQLite database file.
    nonisolated let databaseURL: URL

    /// playhead-6boz: when non-nil, the on-disk file at `databaseURL` is
    /// expected to live inside an Application Support container that may
    /// not exist yet on first launch. `ensureOpen()` performs the
    /// `createDirectory` + Data Protection setattr work the first time.
    /// `path:` initializers (e.g. `:memory:`, raw test paths) skip that
    /// dance entirely (this is `nil` for them).
    nonisolated private let containerDirectoryToCreate: URL?

    /// playhead-6boz: the raw string handed to `sqlite3_open_v2` from
    /// `ensureOpen()`. For the `directory:` initializer this is
    /// `databaseURL.path`. For the `path:` initializer it's the literal
    /// path string the caller supplied (preserving `:memory:`, which
    /// `URL(fileURLWithPath:)` would mangle into a cwd-rooted path).
    nonisolated private let sqliteOpenPath: String

    /// playhead-6boz: schema-readiness flag. Flips to `true` after the
    /// first successful `ensureOpen()` (open + pragmas + migration).
    /// Public read surface is `isOpen` (async, actor-isolated).
    private var didOpen: Bool = false

    // MARK: Lifecycle

    /// playhead-6boz: lightweight initializer. Records the target sqlite
    /// path only; defers `createDirectory`, `sqlite3_open_v2`, the Data
    /// Protection setattr dance, and schema DDL to the first `ensureOpen()`
    /// call (driven by any public method, or by an explicit
    /// `await store.migrate()` / `await store.awaitReady()` from the
    /// caller).
    ///
    /// Why lazy: `PlayheadRuntime.init` runs synchronously from
    /// `PlayheadApp`'s init and extends the launch-storyboard window —
    /// every byte of work in this constructor blocks the splash defense
    /// that lives in SwiftUI-land (see jncn/jndk/hkn1 for the cohort of
    /// fixes this completes). Moving open + DDL to first-use lands the
    /// expense inside a deferred Task, off the main thread, after the
    /// app's launch screen has already given way to a real surface.
    ///
    /// Source-canary
    /// (`AnalysisStoreInitLazinessSourceCanaryTests`) pins this body
    /// against accidentally re-introducing `sqlite3_open_*`,
    /// `FileManager.default.createDirectory`, or `try .write(` calls.
    init(directory: URL? = nil) throws {
        let dir = directory ?? Self.defaultDirectory()
        let dbURL = dir.appendingPathComponent("analysis.sqlite")
        self.containerDirectoryToCreate = dir
        self.databaseURL = dbURL
        self.sqliteOpenPath = dbURL.path
    }

    /// Lightweight initializer for an explicit SQLite path, including
    /// `:memory:` for ephemeral in-memory databases (useful in unit
    /// tests). The on-disk handle is opened lazily — see `init(directory:)`.
    init(path: String) throws {
        // `:memory:` is a special SQLite URI handled by the C API
        // directly (sqlite3_open_v2). `databaseURL` is metadata only;
        // the DB opens via the literal path string preserved in
        // `sqliteOpenPath`.
        self.containerDirectoryToCreate = nil
        self.databaseURL = URL(fileURLWithPath: path)
        self.sqliteOpenPath = path
    }

    /// Convenience factory that returns a lazily-initialized store and
    /// eagerly runs migrations in one call. The eager `migrate()` here
    /// is preserved for callers that want a fully-bootstrapped handle —
    /// production launch paths now skip this and let `ensureOpen()` fire
    /// at first use.
    static func open(directory: URL? = nil) async throws -> AnalysisStore {
        let store = try AnalysisStore(directory: directory)
        try await store.migrate()
        return store
    }

    /// playhead-6boz: schema-readiness signal for callers that should
    /// treat an unopened store as "no data yet" rather than block. UI
    /// providers (`ActivitySnapshotProvider`) read this to early-return
    /// an empty list — opening DDL inside a `@MainActor` refresh is the
    /// hkn1 freeze pattern this rail prevents.
    var isOpen: Bool { didOpen }

    /// playhead-6boz: schema-readiness signal for callers that genuinely
    /// need to block until DDL is ready (`BackfillJobRunner` runs on a
    /// background actor; waiting is fine). Idempotent: subsequent calls
    /// observe the already-open handle and short-circuit.
    func awaitReady() async throws {
        try ensureOpen()
    }

    /// playhead-6boz: idempotent first-use bootstrap. Creates the
    /// container directory, opens `sqlite3`, applies the
    /// `.completeUntilFirstUserAuthentication` Data Protection class,
    /// configures pragmas, and runs schema migration. After a successful
    /// pass `didOpen` flips to `true` and the body short-circuits on
    /// every subsequent call. All public actor methods funnel through
    /// this guard (via `exec`/`prepare` and explicit `try ensureOpen()`
    /// at the public-entry layer) so a caller racing `PlayheadRuntime`'s
    /// deferred warmup never observes a half-built database.
    ///
    /// Re-entrancy: `runSchemaMigration()` calls `exec` / `prepare`,
    /// which themselves call `ensureOpen()`. To break the cycle we flip
    /// `didOpen = true` BEFORE invoking `runSchemaMigration` and roll
    /// it back on error. This is safe because by that point the SQLite
    /// handle has been opened, so the inner `exec` calls just observe
    /// `didOpen == true` and pass straight through.
    ///
    /// On migration failure the handle is closed and `db` reset so a
    /// subsequent `ensureOpen()` retries from the top. Production
    /// callers should not retry — a DDL failure on the analysis store
    /// is fatal for the pre-analysis pipeline — but tests that
    /// intentionally seed a corrupt DB and then recover are supported.
    private func ensureOpen() throws {
        if didOpen { return }
        try openSQLiteHandle()

        // Step 4: schema migration (pragmas, CREATE TABLE, V*IfNeeded
        // ladder). Flip `didOpen = true` BEFORE invoking the migration
        // so the inner `exec` / `prepare` re-entrancy guards
        // short-circuit. On any thrown error, roll `didOpen` back to
        // false and close the handle so a retry path observes a clean
        // slate. `runSchemaMigration` is internally transactional with
        // ROLLBACK on error so the file itself is left consistent.
        didOpen = true
        do {
            try runSchemaMigration()
        } catch {
            didOpen = false
            closeHandleAfterFailedOpen()
            throw error
        }
    }

    /// Steps 1–3 of `ensureOpen()`: container directory, `sqlite3_open_v2`,
    /// Data Protection re-stamp. Deliberately does NOT touch `didOpen` and
    /// does NOT run any SQL, so a caller can decide for itself what the
    /// freshly-opened handle should be initialised with. `ensureOpen()`
    /// follows it with `runSchemaMigration()`; the DEBUG-only
    /// `openWithoutSchemaMigrationForTesting()` follows it with pragmas
    /// alone.
    private func openSQLiteHandle() throws {
        // Step 1: directory + Data Protection. The path-form initializer
        // sets `containerDirectoryToCreate` to `nil` so this step is a
        // no-op for `:memory:` and raw-path test stores.
        if let dir = containerDirectoryToCreate {
            let fm = FileManager.default
            if !fm.fileExists(atPath: dir.path) {
                try fm.createDirectory(at: dir, withIntermediateDirectories: true)
            }
            // Why `.completeUntilFirstUserAuthentication` rather than
            // `.complete`: the app is woken by `BGProcessingTask` and
            // `BGAppRefreshTask` while the device may still be locked.
            // `.complete` renders the SQLite file unreadable in that
            // window, which previously triggered a 4× repro'd crash
            // chain in `PlayheadRuntime.init` (open fails → retry fails
            // → `try!` on the tmp fallback traps).
            // `.completeUntilFirstUserAuthentication` keeps the file
            // protected while the device is at rest pre-unlock and
            // makes it accessible for the rest of the boot session once
            // the user has authenticated at least once, which is the
            // envelope every BGTask runs in.
            // Applied unconditionally (not only on first create) so
            // existing `.complete`-protected installs get migrated to
            // the new class on the next launch.
            try? fm.setAttributes(
                [.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication],
                ofItemAtPath: dir.path
            )
        }

        // Step 2: open the SQLite handle.
        var handle: OpaquePointer?
        // NOMUTEX: the enclosing actor already serializes all access,
        // so the full-mutex threading mode is redundant overhead.
        let flags = SQLITE_OPEN_CREATE | SQLITE_OPEN_READWRITE | SQLITE_OPEN_NOMUTEX
        let rc = sqlite3_open_v2(sqliteOpenPath, &handle, flags, nil)
        guard rc == SQLITE_OK, let handle else {
            let msg = handle.flatMap { String(cString: sqlite3_errmsg($0)) } ?? "unknown"
            if let handle { sqlite3_close_v2(handle) }
            throw AnalysisStoreError.openFailed(code: rc, message: msg)
        }
        self.db = handle

        // Step 3: re-stamp the file's protection class. On installs that
        // predate `.completeUntilFirstUserAuthentication` the file
        // inherited `.complete` from the dir at creation time, so we
        // re-stamp it alongside the dir on every `ensureOpen`.
        if containerDirectoryToCreate != nil {
            try? FileManager.default.setAttributes(
                [.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication],
                ofItemAtPath: databaseURL.path
            )
        }
    }

    /// Shared failure tail: close the handle and reset `db` so a subsequent
    /// `ensureOpen()` retries from the top rather than reusing a handle
    /// whose initialisation threw.
    private func closeHandleAfterFailedOpen() {
        if let h = self.db {
            sqlite3_close_v2(h)
            self.db = nil
        }
    }

    #if DEBUG
    /// playhead-6av0 REVIEW R2 — the fix for a seam that had been silently
    /// vacuous since playhead-6boz.
    ///
    /// `migrateOnlyForTesting()` exists to run the `V*IfNeeded` ladder
    /// WITHOUT `createTables()` painting every table into its head shape
    /// first — that masking is the whole reason the seam was written
    /// (`MigrationLadderTests` cycle-4 H1). But after playhead-6boz turned
    /// `migrate()` into a lazy `ensureOpen()` bootstrap, EVERY SQL surface
    /// began routing through `ensureOpen()`, and the seam's own first
    /// statement is SQL. On a store nobody had opened yet, that first
    /// statement ran the entire real `runSchemaMigration()` — `createTables()`
    /// and the full ladder — before the seam's first rung was consulted. The
    /// seam then re-ran against a database already at head, where every rung
    /// guards itself out. Measured in review round 2: with the ENTIRE body of
    /// `migrateOnlyForTesting()` after its first statement deleted, three
    /// `MigrationLadderTests` cases and the V29/V30/V31 ladder tests all
    /// stayed green.
    ///
    /// This is the missing rung: open the handle and apply pragmas, flip
    /// `didOpen`, and stop — no `createTables()`, no ladder. A store that is
    /// ALREADY open (the correct pattern, and what the V39/V40 tests use:
    /// `migrate()`, rewind `schema_version`, then run the seam) short-circuits
    /// on `didOpen` exactly as before, so this changes nothing for them.
    ///
    /// Pragmas are applied because `runSchemaMigration()` applies them first
    /// too, and the ladder's behaviour genuinely depends on them —
    /// `foreign_keys` defaults OFF, and the V39 re-point's `ON DELETE
    /// CASCADE` / `RESTRICT` handling would otherwise be tested against
    /// semantics production never runs under.
    func openWithoutSchemaMigrationForTesting() throws {
        if didOpen { return }
        try openSQLiteHandle()
        didOpen = true
        do {
            try configurePragmas()
        } catch {
            didOpen = false
            closeHandleAfterFailedOpen()
            throw error
        }
    }
    #endif

    /// Tracks which database paths have already been migrated in this process
    /// to avoid redundant DDL work on repeated `open()` calls.
    private static let migratedLock = NSLock()
    nonisolated(unsafe) private static var migratedPaths: Set<String> = []

    /// Public migration entry point. Idempotent. After playhead-6boz this
    /// is a thin shim that funnels through the lazy `ensureOpen()` path —
    /// the open + pragmas + DDL all run together on first call. Production
    /// callers (`PlayheadRuntime`'s deferred init Task) `await` this once
    /// off-main so the first hot-path query sees an already-bootstrapped
    /// store. Tests and re-entrant callers are safe; subsequent calls
    /// observe `didOpen == true` and short-circuit.
    func migrate() throws {
        try ensureOpen()
    }

    /// playhead-6boz: the body of the original `migrate()`. Run pragmas
    /// and create all tables / indexes / FTS triggers. Safe to call more
    /// than once. Pragmas are always (re)applied since they live on the
    /// per-connection state, not on the database file. The schema DDL
    /// itself only runs once per database path per process — every DDL
    /// statement uses IF NOT EXISTS so re-running is correct, just
    /// unnecessary work.
    ///
    /// Privately invoked from `ensureOpen()` only. Callers MUST NOT call
    /// this directly — `ensureOpen()` is the gate that guarantees the
    /// SQLite handle has been created and that `didOpen` is set after a
    /// clean run.
    private func runSchemaMigration() throws {
        // M4 fix: pragmas must be applied to *every* connection. The previous
        // implementation short-circuited the entire migrate() call when the
        // path had already been seen, leaving second-instance connections with
        // foreign_keys=OFF, the default journal mode, and no busy_timeout.
        try configurePragmas()

        // C-1: hold the migration lock for the entire body, NOT just the
        // cache check. Two stores opening the same path concurrently used
        // to race: the loser skipped migration on a partially-built DB.
        //
        // C-1 (part 2): validate that the sqlite file on disk still exists
        // before trusting the cache. If the file was deleted (test teardown,
        // user clearing Library/Caches, etc.), drop the stale cache entry
        // and re-run migration against the fresh file. Previously the
        // cache short-circuited and returned a store whose tables did not
        // exist, blowing up on the first query.
        //
        // C-1 (part 3): mark `migratedPaths` only AFTER a successful COMMIT.
        // On any rollback path the path stays out of the cache so a retry
        // re-runs migration rather than silently accepting a half-built DB.
        let path = databaseURL.path
        Self.migratedLock.lock()
        defer { Self.migratedLock.unlock() }

        // The sqlite file may have been deleted out from under the static
        // cache since the last open on this path (test cleanup, user
        // clearing Library/Caches, etc.). `sqlite3_open_v2` with
        // `SQLITE_OPEN_CREATE` will have just recreated it as an empty
        // database, so we can't trust the filesystem presence check alone.
        // Instead, probe for the `_meta` table that `createTables()` always
        // builds: its absence means this connection is looking at a fresh
        // DB that still needs migration, regardless of the cache.
        if Self.migratedPaths.contains(path) {
            if try tableExists("_meta") {
                return
            }
            Self.migratedPaths.remove(path)
        }

        // H-5: wrap the whole migrate body in BEGIN IMMEDIATE … COMMIT so
        // a crash mid-migration cannot leave DDL applied without the
        // matching _meta schema_version row. SQLite supports transactional
        // DDL, so table creation, ALTER TABLE, and the version write all
        // roll back together on any thrown error.
        try exec("BEGIN IMMEDIATE")
        do {
            try createTables()
            // Ordering: transcript_chunks Phase 1 runs before the V*IfNeeded
            // ladder; the backfill only depends on columns `createTables()` has
            // already (re)asserted.
            //
            // playhead-jc42 CORRECTED THE REASON THIS LINE USED TO GIVE. It read
            // "...because no later migration touches `transcript_chunks` or
            // `transcript_chunks_fts`, so its FTS rebuild cannot be undone
            // downstream". V53 touches BOTH — it DELETEs duplicate rows and
            // rebuilds the FTS index itself — so that premise is no longer true
            // and must not be relied on by whoever adds V54.
            //
            // The ordering is still correct, for a narrower reason: Phase 1
            // MUTATES rows (`transcriptVersion`/`atomOrdinal`) through the FTS
            // UPDATE trigger, so it needs a healthy index before it runs, and
            // running first is how it gets one. What changed is that a later
            // rung may now legitimately need its OWN rebuild, and V53 carries
            // one. Do not delete a downstream rebuild on the strength of this
            // one having happened: Phase 1's is CONDITIONAL — it fires only
            // inside the `while` loop over assets holding `pass != 'fast'` rows
            // with a NULL `transcriptVersion` or `atomOrdinal`, so a database
            // whose legacy backfill has already completed gets no rebuild here
            // at all. That is exactly the population V53's own rebuild protects,
            // and it is why mutation rail JC08 survived until its fixture
            // stopped seeding rows that trip this one.
            try migrateTranscriptChunksPhase1()
            try writeInitialSchemaVersionIfNeeded()
            // Cycle 1 M5: leave a fault-level forensic trail when this binary
            // opens a database stamped at a newer schema than it knows how to
            // migrate. The V*IfNeeded ladder short-circuits per migration
            // (`guard schemaVersion < N`), so a downgrade silently continues
            // with whatever columns happen to overlap — only the support log
            // distinguishes "v22 store under v26 binary" from "v22 store under
            // v22 binary". Continue running rather than blocking; the worst
            // case is the same as today, just visible.
            let observedSchemaVersion = (try? schemaVersion()) ?? nil
            if let observed = observedSchemaVersion, observed > Self.currentSchemaVersion {
                logger.fault(
                    "AnalysisStore opened a newer schema than this binary supports: observed=\(observed, privacy: .public) expected<=\(Self.currentSchemaVersion, privacy: .public). Behavior may diverge from a freshly-migrated store; downgrade is not officially supported."
                )
            }
            try migrateEvidenceEventsNaturalKeyV2IfNeeded()
            try migrateEvidenceEventsTranscriptVersionV3IfNeeded()
            try migrateAnalysisSessionsShadowRetryV4IfNeeded()
            try migratePodcastPlannerStateV4IfNeeded()
            try migrateAdWindowsPhase6PrepV5IfNeeded()
            try migrateCorrectionEventsV6IfNeeded()
            // Cycle 8 reconciliation: both C4 (Rev3-M5 shadow/targeted) and
