            // shipped as a migration.
            try migrateSemanticScanVerdictProvenanceV61IfNeeded()
            try exec("COMMIT")
        } catch {
            try? exec("ROLLBACK")
            throw error
        }

        // Only mark as migrated after a successful COMMIT.
        Self.migratedPaths.insert(path)
    }

