                    correction,
                    source: .bannerSuggestionDenied,
                    analysisAssetId: analysisAssetId,
                    startTime: expectedStartTime,
                    endTime: expectedEndTime,
                    requiredTargetIDs: [windowId],
                    expectedProjection:
                        ExplicitFeedbackDetectionProjection(
                            expectedProducerRevision
                        )
