    private func feedbackAssetMatches(
        analysisAssetId: String,
        expectedEpisodeId: String
    ) throws -> Bool {
        guard !expectedEpisodeId.isEmpty,
              let asset = try fetchAsset(id: analysisAssetId)
        else {
            return false
        }
        return asset.episodeId == expectedEpisodeId
    }

    private func markAdWindowAppliedForFeedback(
        id: String,
        analysisAssetId: String
    ) throws {
        let sql = """
            UPDATE ad_windows
            SET decisionState = ?, wasSkipped = 1
            WHERE id = ? AND analysisAssetId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, AdDecisionState.applied.rawValue)
        bind(stmt, 2, id)
        bind(stmt, 3, analysisAssetId)
        try step(stmt, expecting: SQLITE_DONE)
        guard sqlite3_changes(db) > 0 else {
            throw AnalysisStoreError.notFound
        }
    }

    private static func feedbackCorrectionMatches(
        _ correction: CorrectionEvent,
        source: CorrectionSource,
        analysisAssetId: String,
        startTime: Double,
        endTime: Double,
        requiredTargetIDs: Set<String>,
        expectedProjection: ExplicitFeedbackDetectionProjection
    ) -> Bool {
        guard correction.analysisAssetId == analysisAssetId,
              correction.source == source,
              correction.effectiveCorrectionType
                == source.kind.correctionType,
              let refs = correction.targetRefs,
              let canonicalTargetIDs =
                refs.canonicalExplicitAdWindowIDs,
              refs.explicitFeedbackDetectionProjection
                == expectedProjection,
              let scope = CorrectionScope.deserialize(correction.scope),
              case let .exactTimeSpan(assetId, storedStart, storedEnd)
                = scope,
              assetId == analysisAssetId,
              correction.scope == CorrectionScope.exactTimeSpan(
                assetId: analysisAssetId,
                startTime: startTime,
                endTime: endTime
              ).serialized
        else {
            return false
        }
        if let exactSpan = refs.exactFeedbackSpan {
            guard exactSpan.matches(
                startTime: startTime,
                endTime: endTime
            ) else {
                return false
            }
        } else {
            // Legacy receipts did not retain sub-millisecond material. They
            // remain valid only when the old scope round-trip is itself exact;
            // ambiguous sub-millisecond receipts fail closed.
            guard storedStart == startTime,
                  storedEnd == endTime
            else {
                return false
            }
        }
        return Set(canonicalTargetIDs) == requiredTargetIDs
    }

    /// Reload the row selected by the v32 semantic identity and require the
    /// private receipt body to be exactly the one the atomic feedback action
    /// validated before any AdWindow mutation commits.
    ///
    /// In particular, the explicit upsert never overwrites an existing
    /// `targetRefsJSON` body. A same-route/same-target retry increments its
    /// submission counter only when the stored projection is identical; a
    /// corrupt/mismatched survivor makes this check return false and the
    /// surrounding transaction rolls the audit bump back as well.
    private func persistedExplicitCorrectionMatchesExpected(
        _ expected: CorrectionEvent
    ) throws -> Bool {
        guard expected.source?.isExplicitBannerFeedback == true,
              let identityKey = expected.explicitReceiptIdentityKey,
              let expectedTargetRefs = expected.targetRefs
        else {
            return false
        }
        let normalizedScopeKey =
            CorrectionScope.deserialize(expected.scope)?.normalizedIdentityKey
            ?? expected.scope
        let sql = """
            SELECT analysisAssetId, scope, source, correctionType,
                   targetRefsJSON, effectiveCorrectionType,
                   normalizedScopeKey, correctionIdentityKey
            FROM correction_events
            WHERE analysisAssetId = ?
              AND effectiveCorrectionType = ?
              AND normalizedScopeKey = ?
              AND correctionIdentityKey = ?
            LIMIT 1
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, expected.analysisAssetId)
        bind(stmt, 2, expected.effectiveCorrectionType.rawValue)
        bind(stmt, 3, normalizedScopeKey)
        bind(stmt, 4, identityKey)
        guard sqlite3_step(stmt) == SQLITE_ROW,
              text(stmt, 0) == expected.analysisAssetId,
              text(stmt, 1) == expected.scope,
              optionalText(stmt, 2) == expected.source?.rawValue,
              optionalText(stmt, 3) == expected.correctionType?.rawValue,
              text(stmt, 5) == expected.effectiveCorrectionType.rawValue,
              text(stmt, 6) == normalizedScopeKey,
              text(stmt, 7) == identityKey,
              let refsJSON = optionalText(stmt, 4),
              let refsData = refsJSON.data(using: .utf8),
              let persistedTargetRefs = try? JSONDecoder().decode(
                  CorrectionTargetRefs.self,
                  from: refsData
              ),
              persistedTargetRefs == expectedTargetRefs
        else {
            return false
        }
        return true
    }

    /// Atomically promotes one persisted window only while both its durable
    /// state and producer revision still permit the skip that scheduled this
    /// write. SkipOrchestrator publishes cues synchronously and persists the
    /// promotion in a child task. Before that task reaches this actor, a
    /// No/Listen transaction can make the row terminal, or a reconcile can
    /// replace a non-terminal same-ID row with materially revised producer
    /// data. The store actor serializes the revision read and conditional
    /// update, so neither case can promote the replacement revision.
    ///
    /// `decisionState`, `wasSkipped`, and `userDismissedBanner` are mutable
    /// response fields rather than producer revision identity. All remaining
    /// persisted producer fields participate in the fence.
    @discardableResult
    func persistAppliedAdWindowIfEligible(
        windowId: String,
        analysisAssetId: String,
        expectedProducerRevision: AdWindow
    ) throws -> Bool {
        guard windowId == expectedProducerRevision.id,
              analysisAssetId == expectedProducerRevision.analysisAssetId,
              let current = try fetchAdWindow(id: windowId),
              current.analysisAssetId == analysisAssetId,
              Self.sameAdWindowProducerRevision(
                current,
                expectedProducerRevision
              ),
              [
                AdDecisionState.candidate.rawValue,
                AdDecisionState.confirmed.rawValue,
                AdDecisionState.applied.rawValue,
              ].contains(current.decisionState)
        else {
            return false
        }

        let sql = """
            UPDATE ad_windows
            SET decisionState = ?, wasSkipped = 1
            WHERE id = ?
              AND analysisAssetId = ?
              AND decisionState = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, AdDecisionState.applied.rawValue)
        bind(stmt, 2, windowId)
        bind(stmt, 3, analysisAssetId)
        bind(stmt, 4, current.decisionState)
        try step(stmt, expecting: SQLITE_DONE)
        return sqlite3_changes(db) > 0
    }

    private static func sameAdWindowProducerRevision(
        _ lhs: AdWindow,
        _ rhs: AdWindow
    ) -> Bool {
        AdWindowMaterialIdentity.sameProducerRevision(lhs, rhs)
    }

    func updateAdWindowHotPathCandidate(_ ad: AdWindow) throws {
        let sql = """
            UPDATE ad_windows SET
                startTime = ?, endTime = ?, confidence = ?, boundaryState = ?,
                advertiser = ?, product = ?, adDescription = ?,
                evidenceText = ?, evidenceStartTime = ?, metadataSource = ?,
                metadataConfidence = ?, metadataPromptVersion = ?,
                evidenceSources = ?, eligibilityGate = ?,
                catalogStoreMatchSimilarity = ?, catalogFingerprintVersion = ?,
                catalogMatchedEntryId = ?, catalogMatchedShowId = ?,
                catalogMatchedLearningSource = ?,
                catalogMatchedLearningLifecycle = ?, startEdgeAnchor = ?,
                endEdgeAnchor = ?, skipConfidence = ?
            WHERE id = ? AND analysisAssetId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, ad.startTime)
        bind(stmt, 2, ad.endTime)
        bind(stmt, 3, ad.confidence)
        bind(stmt, 4, ad.boundaryState)
        bind(stmt, 5, ad.advertiser)
        bind(stmt, 6, ad.product)
        bind(stmt, 7, ad.adDescription)
        bind(stmt, 8, ad.evidenceText)
        bind(stmt, 9, ad.evidenceStartTime)
        bind(stmt, 10, ad.metadataSource)
        bind(stmt, 11, ad.metadataConfidence)
        bind(stmt, 12, ad.metadataPromptVersion)
        bind(stmt, 13, ad.evidenceSources)
        bind(stmt, 14, ad.eligibilityGate)
        bind(stmt, 15, ad.catalogStoreMatchSimilarity)
        bind(stmt, 16, ad.catalogFingerprintVersion)
        bind(stmt, 17, ad.catalogMatchedEntryId)
        bind(stmt, 18, ad.catalogMatchedShowId)
        bind(stmt, 19, ad.catalogMatchedLearningSource)
        bind(stmt, 20, ad.catalogMatchedLearningLifecycle)
        bind(stmt, 21, ad.startEdgeAnchor)
        bind(stmt, 22, ad.endEdgeAnchor)
        // playhead-ar60: `confidence` and `skipConfidence` are ONE
        // observation and are always written together. An UPDATE that
        // rewrote only `confidence` would leave the actuation column
        // describing a decision that no longer exists — the same
        // two-quantities-one-column failure this bead removed, arrived at by
        // a stale write instead of a mislabelled one.
        bind(stmt, 23, ad.skipConfidence)
        bind(stmt, 24, ad.id)
        bind(stmt, 25, ad.analysisAssetId)
        try step(stmt, expecting: SQLITE_DONE)
        guard sqlite3_changes(db) == 1 else {
            throw AnalysisStoreError.staleAdWindowRevision(id: ad.id)
        }
    }

    func insertAdWindows(_ windows: [AdWindow]) throws {
        guard !windows.isEmpty else { return }
        try exec("BEGIN TRANSACTION")
        do {
            for ad in windows {
                try insertAdWindow(ad)
            }
            try exec("COMMIT")
        } catch {
            try? exec("ROLLBACK")
            throw error
        }
    }

    func upsertHotPathAdWindows(
        _ windows: [AdWindow],
        existingIDs: Set<String>,
        retiredIDs: Set<String> = [],
        expectedProducerRevisions: [String: AdWindow] = [:]
    ) throws {
        guard !windows.isEmpty || !retiredIDs.isEmpty else { return }
        try exec("BEGIN TRANSACTION")
        do {
            let windowIDs = Set(windows.map(\.id))
            guard windowIDs.count == windows.count,
                  existingIDs.isSubset(of: windowIDs),
                  retiredIDs.isDisjoint(with: windowIDs),
                  existingIDs.isDisjoint(with: retiredIDs) else {
                throw AnalysisStoreError.queryFailed(
                    "Invalid hot-path reconcile mutation set"
                )
            }

            // Validate every ID-backed mutation before writing any row. The
            // actor serializes this transaction, so the revisions cannot
            // change between these reads and the update/delete statements.
            for id in existingIDs.union(retiredIDs).sorted() {
                guard let expected = expectedProducerRevisions[id],
                      expected.id == id,
                      expected.decisionState
                        == AdDecisionState.candidate.rawValue,
                      let current = try fetchAdWindow(id: id),
                      current.decisionState == expected.decisionState,
                      current.wasSkipped == expected.wasSkipped,
                      current.userDismissedBanner
                        == expected.userDismissedBanner,
                      Self.sameAdWindowProducerRevision(current, expected)
                else {
                    throw AnalysisStoreError.staleAdWindowRevision(id: id)
                }
                if existingIDs.contains(id) {
                    guard let incoming = windows.first(where: { $0.id == id }),
                          incoming.analysisAssetId
                            == expected.analysisAssetId else {
                        throw AnalysisStoreError.staleAdWindowRevision(id: id)
                    }
                }
            }

            for ad in windows {
                if existingIDs.contains(ad.id) {
                    try updateAdWindowHotPathCandidate(ad)
                } else {
                    try insertAdWindow(ad)
                }
            }
            if !retiredIDs.isEmpty {
                try deleteAdWindows(ids: retiredIDs)
            }
            try exec("COMMIT")
        } catch {
            try? exec("ROLLBACK")
            throw error
        }
    }

    /// playhead-w17m: decision states that are terminal user-facing history — a
    /// skip that was applied to the listener (`.applied`) or an ad the user
    /// listened through (`.reverted`). Held as raw string literals (not
    /// `AdDecisionState`) because the persistence layer is deliberately decoupled
    /// from the orchestrator's decision enum for I/O (see `AdWindow.decisionState`
    /// / `startEdgeAnchor`). Pinned to `AdDecisionState.applied.rawValue` /
    /// `.reverted.rawValue`; the SAME terminal set `SkipOrchestrator.retireAdWindows`
    /// guards on (SkipOrchestrator ~1264) and that
    /// `AdDetectionService.reconcilableBackfillDecisionStates` excludes.
    static let terminalAdDecisionStates: Set<String> = ["applied", "reverted"]

    /// playhead-w17m: read a single ad_window's current `decisionState` by id.
    /// Deliberately a lightweight `SELECT decisionState` (not `fetchAdWindow`'s
    /// `SELECT *`) so the reconcile terminal-guard read is cheap. Returns nil when
    /// no such row exists. Runs on the store's single connection, so when called
    /// inside a `BEGIN…COMMIT` it observes that transaction's live (uncommitted)
    /// state — which is exactly why it closes the ud4n snapshot race.
    private func adWindowDecisionState(id: String) throws -> String? {
        let sql = "SELECT decisionState FROM ad_windows WHERE id = ? LIMIT 1"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, id)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return text(stmt, 0)
    }

    /// playhead-ud4n: atomic backfill reconciliation. Sibling of
    /// `upsertHotPathAdWindows`. In ONE BEGIN…COMMIT/ROLLBACK transaction:
    /// INSERT-OR-REPLACE each authoritative fusion window (content-addressed ids
    /// make an unchanged rerun a no-op) then hard-DELETE the retired ids. Either
    /// both land or neither does, so an interrupted backfill never leaves the
    /// row set half-reconciled (a superseded hot row deleted while its fusion
    /// replacement failed to insert, or vice versa). No schema change:
    /// `ad_windows.id` is a TEXT PK with no child FK, so REPLACE and DELETE are
    /// free of cascade side effects.
    ///
    /// playhead-w17m — store-level atomic terminal guard. Before each
    /// INSERT-OR-REPLACE, read the target id's LIVE (in-transaction) decisionState
    /// and SKIP the write when it is terminal (`.applied` / `.reverted`), leaving
    /// the terminal row untouched. `AdDetectionService.reconcileBackfillWindows`
    /// already drops protected ids from the persist set, but it computes that
    /// protected set from a snapshot read taken OUTSIDE this transaction: a
    /// `candidate → .applied` transition landing between that snapshot and this
    /// write is invisible to it, and because fusion ids are content-addressed
    /// (ordinal-keyed, not decisionState-keyed) the rerun mints the SAME id, so a
    /// blind REPLACE would clobber the just-applied terminal row back to
    /// `.confirmed` (losing `wasSkipped`) — corrupting DB history. This guard runs
    /// against live DB state INSIDE the transaction, so it closes that race
    /// regardless of what the outer snapshot saw. It composes with (does not
    /// replace) the detection-level guard — belt and suspenders. Non-existing id
    /// or non-terminal existing → write as before (idempotency preserved).
    ///
    /// The DELETE path carries the SAME guard, symmetrically. `retiredIDs` is
    /// computed from that OUT-OF-TRANSACTION snapshot too, so an id that was
    /// reconcilable at snapshot time can flip to terminal (`.applied` /
    /// `.reverted`) in the race window and land in it — and an unconditional
    /// DELETE would drop the just-applied terminal row's user-facing history
    /// (`decisionState` + `wasSkipped`), from which a relaunch preload could
    /// re-surface the span, even though the in-memory
    /// `SkipOrchestrator.retireAdWindows` (SkipOrchestrator ~1259) ALREADY
    /// refuses to retire terminal rows. So before deleting, each retired id's
    /// LIVE in-transaction decisionState is read via the same helper and terminal
    /// ids are filtered OUT of the delete (non-terminal / non-existing ids delete
    /// as before). This keeps the store's DELETE path matching the in-memory
    /// retire guard, atomically on the same connection.
    func reconcileBackfillAdWindows(
        _ windows: [AdWindow],
        retiredIDs: Set<String>
    ) throws {
        guard !windows.isEmpty || !retiredIDs.isEmpty else { return }
        try exec("BEGIN TRANSACTION")
        do {
            for ad in windows {
                // Atomic terminal guard: never overwrite an existing row whose
                // live decisionState is terminal.
                if let existing = try adWindowDecisionState(id: ad.id),
                   Self.terminalAdDecisionStates.contains(existing) {
                    continue
                }
                try insertOrReplaceAdWindow(ad)
            }
            if !retiredIDs.isEmpty {
                // Atomic terminal guard on the DELETE path, symmetric to the
                // INSERT-OR-REPLACE guard above: filter out any retired id whose
                // live (in-transaction) decisionState is terminal, then delete
                // the rest. Non-terminal / non-existing ids delete as before.
                var deletableIDs = Set<String>()
                for id in retiredIDs {
                    if let existing = try adWindowDecisionState(id: id),
                       Self.terminalAdDecisionStates.contains(existing) {
                        continue
                    }
                    deletableIDs.insert(id)
                }
                if !deletableIDs.isEmpty {
                    try deleteAdWindows(ids: deletableIDs)
                }
            }
            try exec("COMMIT")
        } catch {
            try? exec("ROLLBACK")
            throw error
        }
    }

    private func deleteAdWindows(ids: Set<String>) throws {
        guard !ids.isEmpty else { return }
        let sql = "DELETE FROM ad_windows WHERE id = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        for id in ids {
            sqlite3_reset(stmt)
            sqlite3_clear_bindings(stmt)
            bind(stmt, 1, id)
            try step(stmt, expecting: SQLITE_DONE)
        }
    }

    @discardableResult
    func updateAdWindowMetadataIfCurrent(
        expectedProducerRevision: AdWindow,
        advertiser: String?,
        product: String?,
        evidenceText: String?,
        metadataSource: String,
        metadataConfidence: Double?,
        metadataPromptVersion: String?
    ) throws -> Bool {
        guard let current = try fetchAdWindow(
                  id: expectedProducerRevision.id
              ),
              current.analysisAssetId
                == expectedProducerRevision.analysisAssetId,
              current.decisionState
                == expectedProducerRevision.decisionState,
              current.wasSkipped == expectedProducerRevision.wasSkipped,
              current.userDismissedBanner
                == expectedProducerRevision.userDismissedBanner,
              Self.sameAdWindowProducerRevision(
                  current,
                  expectedProducerRevision
              ) else {
            return false
        }
        let sql = """
            UPDATE ad_windows SET
                advertiser = ?, product = ?, evidenceText = ?,
                metadataSource = ?, metadataConfidence = ?, metadataPromptVersion = ?
            WHERE id = ? AND analysisAssetId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, advertiser)
        bind(stmt, 2, product)
        bind(stmt, 3, evidenceText)
        bind(stmt, 4, metadataSource)
        bind(stmt, 5, metadataConfidence)
        bind(stmt, 6, metadataPromptVersion)
        bind(stmt, 7, expectedProducerRevision.id)
        bind(stmt, 8, expectedProducerRevision.analysisAssetId)
        try step(stmt, expecting: SQLITE_DONE)
        return sqlite3_changes(db) == 1
    }

    func updateAdWindowWasSkipped(id: String, wasSkipped: Bool) throws {
        let sql = "UPDATE ad_windows SET wasSkipped = ? WHERE id = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, wasSkipped ? 1 : 0)
        bind(stmt, 2, id)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// playhead-lc7z / playhead-jw63.1: mark that the user explicitly answered
    /// No to the banner surfaced for this window. The legacy
    /// `userDismissedBanner` schema name is retained for compatibility, but a
    /// neutral x dismissal and passive auto-fade leave it false. Mirror of
    /// `updateAdWindowWasSkipped`; a no-op when `id` matches no row.
    func updateAdWindowUserDismissedBanner(id: String, userDismissedBanner: Bool) throws {
        let sql = "UPDATE ad_windows SET userDismissedBanner = ? WHERE id = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, userDismissedBanner ? 1 : 0)
        bind(stmt, 2, id)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// Asset-scoped counterpart used by suspended Suggest-No transactions.
    /// Throwing on a scope mismatch lets the surrounding transaction roll back
    /// its correction append before it can affect a replacement episode.
    private func updateAdWindowUserDismissedBanner(
        id: String,
        analysisAssetId: String,
        userDismissedBanner: Bool
    ) throws {
        let sql = """
            UPDATE ad_windows
            SET userDismissedBanner = ?
            WHERE id = ? AND analysisAssetId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, userDismissedBanner ? 1 : 0)
        bind(stmt, 2, id)
        bind(stmt, 3, analysisAssetId)
        try step(stmt, expecting: SQLITE_DONE)
        guard sqlite3_changes(db) > 0 else {
            throw AnalysisStoreError.notFound
        }
    }

    func updateConfirmedAdCoverage(id: String, endTime: Double) throws {
        let sql = "UPDATE analysis_assets SET confirmedAdCoverageEndTime = ? WHERE id = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, endTime)
        bind(stmt, 2, id)
        try step(stmt, expecting: SQLITE_DONE)
    }

    func fetchAllFeatureWindows(
        assetId: String,
        minimumFeatureVersion: Int? = FeatureExtractionConfig.default.featureVersion
    ) throws -> [FeatureWindow] {
        let versionClause = minimumFeatureVersion == nil ? "" : "AND featureVersion >= ?"
        let sql = """
            SELECT analysisAssetId, startTime, endTime, rms, spectralFlux,
                   musicProbability, speakerChangeProxyScore, musicBedChangeScore,
                   musicBedOnsetScore, musicBedOffsetScore, musicBedLevelRaw,
                   pauseProbability, speakerClusterId, jingleHash, featureVersion
            FROM feature_windows
            WHERE analysisAssetId = ? \(versionClause)
            ORDER BY startTime
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, assetId)
        if let minimumFeatureVersion {
            bind(stmt, 2, minimumFeatureVersion)
        }
        var results: [FeatureWindow] = []
        while try nextRow(stmt) {
            results.append(try readFeatureWindow(stmt))
        }
        return results
    }

    private func readFeatureWindow(
        _ stmt: OpaquePointer?
    ) throws -> FeatureWindow {
        guard let levelRaw = optionalText(stmt, 10),
              let level = MusicBedLevel(rawValue: levelRaw) else {
            throw AnalysisStoreError.invalidRow(column: 10)
        }
        return FeatureWindow(
            analysisAssetId: text(stmt, 0),
            startTime: sqlite3_column_double(stmt, 1),
            endTime: sqlite3_column_double(stmt, 2),
            rms: sqlite3_column_double(stmt, 3),
            spectralFlux: sqlite3_column_double(stmt, 4),
            musicProbability: sqlite3_column_double(stmt, 5),
            speakerChangeProxyScore: sqlite3_column_double(stmt, 6),
            musicBedChangeScore: sqlite3_column_double(stmt, 7),
            musicBedOnsetScore: sqlite3_column_double(stmt, 8),
            musicBedOffsetScore: sqlite3_column_double(stmt, 9),
            musicBedLevel: level,
            pauseProbability: sqlite3_column_double(stmt, 11),
            speakerClusterId: optionalInt(stmt, 12),
            jingleHash: optionalText(stmt, 13),
            featureVersion: Int(sqlite3_column_int(stmt, 14))
        )
    }

    // Bug 5 (skip-cues-deletion): the `skip_cues` CRUD methods
    // (`insertSkipCue`, `insertSkipCues`, `fetchSkipCues`,
    // `markSkipCueSkipped`, `markSkipCueDismissed`, `readSkipCue`)
    // were deleted along with the table.

    // MARK: - CRUD: trust_episode_observations (playhead-mn5e / 2qz6)

    /// Durably CLAIM one episode's trust observation for one show.
    ///
    /// Returns `true` exactly once per `(podcastId, analysisAssetId)` pair, for
    /// the caller that got there first; every later call for the same pair
    /// returns `false`. That is what stops `observationCount` counting
    /// BACKFILLS: a single asset is backfilled many times — hot path, final
    /// pass, a re-drive, a transcript-version bump, playhead-15d0's resume —
    /// and only the first of those may move the trust ladder.
    ///
    /// **It dedupes the ASSET, which is not quite the episode (playhead-89x6).**
    /// One episode can hold two `analysis_assets` rows, so it can claim twice.
    /// See the table's own comment in `createTables` for the two paths and for
    /// why that residual is bounded at 2 against the ~9 this closes.
    ///
    /// **BOTH WRITERS CLAIM HERE, and that is the point (playhead-fh5v).** The
    /// backfill (`AdDetectionService.recordConfirmedWindowObservation`) and the
    /// banner Yes (`TrustScoringService.recordCorrectObservation`) share this
    /// one key, so whichever arrives first counts the episode and the other
    /// does not count it again. A second incrementer with its own private
    /// notion of "an observation" is what made the counter unauditable before.
    ///
    /// **The claim and the test are ONE statement.** `INSERT … ON CONFLICT DO
    /// NOTHING` plus `sqlite3_changes` cannot interleave the way a
    /// `SELECT`-then-`INSERT` pair can, so two concurrent backfills of the same
    /// asset cannot both read "not yet claimed" and both count. The row is the
    /// claim; there is no separate flag that could disagree with it.
    ///
    /// **The claim is taken only when the observation is actually recorded.**
    /// The caller claims immediately before calling
    /// `TrustScoringService.recordSuccessfulObservation`, so a backfill that
    /// cannot record (no trust service installed) leaves the episode STILL
    /// CLAIMABLE and a later backfill of it counts normally. A claim that
    /// stood for an observation nobody made would silently cost the show an
    /// episode of credit, permanently.
    ///
    /// The pair is keyed on the SHOW as well as the asset, so an asset that
    /// legitimately belongs to a different show (a re-subscribed feed under a
    /// new URL) is a distinct claim rather than a suppressed one.
    func claimEpisodeTrustObservation(
        podcastId: String,
        analysisAssetId: String
    ) throws -> Bool {
        guard !podcastId.isEmpty, !analysisAssetId.isEmpty else { return false }
        let stmt = try prepare("""
            INSERT INTO trust_episode_observations (podcastId, analysisAssetId)
            VALUES (?, ?)
            ON CONFLICT (podcastId, analysisAssetId) DO NOTHING
        """)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, podcastId)
        bind(stmt, 2, analysisAssetId)
        try step(stmt, expecting: SQLITE_DONE)
        return sqlite3_changes(db) > 0
    }

    /// How many distinct episodes have contributed a trust observation to this
    /// show. Diagnostic / test seam: `podcast_profiles.observationCount` is the
    /// value the ladder reads, and this is the independent count it must agree
    /// with. Two numbers that are supposed to be equal, so a drift is
    /// observable rather than inferred.
    func episodeTrustObservationCount(podcastId: String) throws -> Int {
        let stmt = try prepare("""
            SELECT COUNT(*) FROM trust_episode_observations WHERE podcastId = ?
        """)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, podcastId)
        guard try nextRow(stmt) else {
            throw AnalysisStoreError.queryFailed(
                "episode trust-observation count returned no row"
            )
        }
        return Int(sqlite3_column_int64(stmt, 0))
    }

    // MARK: - CRUD: podcast_profiles

    func upsertProfile(_ profile: PodcastProfile) throws {
        // playhead-i9dj: `title` participates in the upsert with
        // COALESCE-preserve semantics — a profile rebuild that doesn't
        // know the title (e.g. TrustScoringService re-upserting a
        // fetched profile) must NOT clobber a previously-recorded
        // title. `COALESCE(excluded.title, podcast_profiles.title)`
        // keeps the existing column when the new write is NULL and
        // overwrites only when the new write carries a non-NULL value.
        //
        // skeptical-review-cycle-17 L-1: ALL OTHER COLUMNS overwrite
        // unconditionally — `excluded.<col>` is written verbatim. In
        // particular, `traitProfileJSON` is NOT COALESCE-protected, so
        // a constructor that defaults it to `nil` will silently nil the
        // persisted trait profile on every upsert. Cycles 15-M-2
        // (`updatePriors`) and 17-M-1 (`recordListenRewind`) both
        // closed instances of that bug. New callers MUST either:
        //   • carry `existing.traitProfileJSON` (and any future
        //     non-COALESCE column) forward inside the closure of an
        //     atomic `mutateProfile` / `updateProfileIfExists` helper, OR
        //   • use a column-specific setter (e.g. `updateProfileTitle`)
        //     that writes only the columns it owns.
        // Adding new non-COALESCE columns to this upsert? Update the
        // canary at PlayheadTests/Services/AdDetection/
        // AdDetectionServiceUpdatePriorsAtomicityCanaryTests.swift to
        // pin the new column's carry-forward invariant in every caller.
        // playhead-084j: `adDurationStatsJSON` carries the per-show observed
        // ad-duration aggregate. Wrapped in COALESCE on the conflict path so a
        // `nil` write (from older callers that pre-date the column) cannot
        // clobber an established aggregate. Same defensive pattern as `title`
        // and the explicit `existing.X` carry-forwards in `mutateProfile`
        // closures.
        // playhead-spxs: `networkId` carries COALESCE-preserve semantics —
        // a profile rebuild that doesn't know the network identity (e.g.
        // trust-scoring) MUST NOT clobber a previously-recorded value.
        // Same defensive shape as `title` and `adDurationStatsJSON`.
        let sql = """
            INSERT INTO podcast_profiles
            (podcastId, sponsorLexicon, normalizedAdSlotPriors, repeatedCTAFragments,
             jingleFingerprints, implicitFalsePositiveCount, skipTrustScore,
             observationCount, mode, recentFalseSkipSignals, traitProfileJSON,
             title, adDurationStatsJSON, networkId, detectorTrustJSON)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(podcastId) DO UPDATE SET
                sponsorLexicon = excluded.sponsorLexicon,
                normalizedAdSlotPriors = excluded.normalizedAdSlotPriors,
                repeatedCTAFragments = excluded.repeatedCTAFragments,
                jingleFingerprints = excluded.jingleFingerprints,
                implicitFalsePositiveCount = excluded.implicitFalsePositiveCount,
                skipTrustScore = excluded.skipTrustScore,
                observationCount = excluded.observationCount,
                mode = excluded.mode,
                recentFalseSkipSignals = excluded.recentFalseSkipSignals,
                traitProfileJSON = excluded.traitProfileJSON,
                title = COALESCE(excluded.title, podcast_profiles.title),
                adDurationStatsJSON = COALESCE(
                    excluded.adDurationStatsJSON,
                    podcast_profiles.adDurationStatsJSON
                ),
                networkId = COALESCE(
                    excluded.networkId,
                    podcast_profiles.networkId
                ),
                detectorTrustJSON = COALESCE(
                    excluded.detectorTrustJSON,
                    podcast_profiles.detectorTrustJSON
                )
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, profile.podcastId)
        bind(stmt, 2, profile.sponsorLexicon)
        bind(stmt, 3, profile.normalizedAdSlotPriors)
        bind(stmt, 4, profile.repeatedCTAFragments)
        bind(stmt, 5, profile.jingleFingerprints)
        bind(stmt, 6, profile.implicitFalsePositiveCount)
        bind(stmt, 7, profile.skipTrustScore)
        bind(stmt, 8, profile.observationCount)
        bind(stmt, 9, profile.mode)
        bind(stmt, 10, profile.recentFalseSkipSignals)
        bind(stmt, 11, profile.traitProfileJSON)
        bind(stmt, 12, profile.title)
        bind(stmt, 13, profile.adDurationStatsJSON)
        bind(stmt, 14, profile.networkId)
        // playhead-gard: COALESCE-protected above, so a rebuild that does not
        // know the ledger (priors update, title write, any pre-gard-shaped
        // caller) writes NULL and preserves what is stored.
        bind(stmt, 15, profile.detectorTrustJSON)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// skeptical-review-cycle-1: atomic read-modify-write helper for
    /// `podcast_profiles`. The pre-existing TrustScoringService pattern
    /// awaited `fetchProfile` then `upsertProfile`, opening an actor-
    /// reentrancy window where a concurrent call could fetch the same
    /// row and overwrite the first writer's increment (lost-update on
    /// `observationCount` / `skipTrustScore`). This helper runs the
    /// fetch + mutate + upsert as a single synchronous body inside the
    /// `AnalysisStore` actor, so no other actor call can interleave
    /// against the same row.
    ///
    /// - Parameters:
    ///   - podcastId: profile key to merge.
    ///   - create: builder for the brand-new row when no profile exists.
    ///   - update: pure transform applied to the existing profile.
    /// - Returns: the resulting `PodcastProfile` that was persisted.
    @discardableResult
    func mutateProfile(
        podcastId: String,
        create: () -> PodcastProfile,
        update: (PodcastProfile) -> PodcastProfile
    ) throws -> PodcastProfile {
        let existing = try fetchProfile(podcastId: podcastId)
        let merged: PodcastProfile = existing.map(update) ?? create()
        try upsertProfile(merged)
        return merged
    }

    /// Sister to `mutateProfile` for callers that must NOT lazy-create
    /// a row — e.g. `recordFalseSkipSignal` only mutates an existing
    /// profile because a missing one means the show has never been
    /// observed and a stub would corrupt the trust priors. Returns
    /// `nil` when no row exists.
    @discardableResult
    func updateProfileIfExists(
        podcastId: String,
        update: (PodcastProfile) -> PodcastProfile
    ) throws -> PodcastProfile? {
        guard let existing = try fetchProfile(podcastId: podcastId) else {
            return nil
        }
        let merged = update(existing)
        try upsertProfile(merged)
        return merged
    }

    /// skeptical-review-cycle-5 L-Y4: tuple-returning variant that lets
    /// the closure surface arbitrary `Sendable` metadata derived from
    /// the pre/post-update transition (e.g. a SkipMode demotion tuple)
    /// without forcing the caller to capture a `nonisolated(unsafe)
    /// var` across the actor hop into `AnalysisStore`. The closure runs
    /// inside the store actor; the captured value rides back across the
    /// hop on the return value, so all data flow is value-typed and
    /// strict-concurrency clean.
    @discardableResult
    func updateProfileIfExistsCapturing<T: Sendable>(
        podcastId: String,
        update: (PodcastProfile) -> (PodcastProfile, T)
    ) throws -> (profile: PodcastProfile, captured: T)? {
        guard let existing = try fetchProfile(podcastId: podcastId) else {
            return nil
        }
        let (merged, captured) = update(existing)
        try upsertProfile(merged)
        return (merged, captured)
    }

    func fetchProfile(podcastId: String) throws -> PodcastProfile? {
        // playhead-i9dj: explicit column list (not `SELECT *`) so future
        // additive migrations don't shift the positional indices the
        // decoder reads. `title` lands at index 11 — append-only.
        // playhead-084j: `adDurationStatsJSON` lands at index 12.
        // playhead-spxs: `networkId` lands at index 13.
        // playhead-xsdz.71: `daiStitchNetwork` at 14, `daiExpected` at 15.
        let sql = """
            SELECT podcastId, sponsorLexicon, normalizedAdSlotPriors, repeatedCTAFragments,
                   jingleFingerprints, implicitFalsePositiveCount, skipTrustScore,
                   observationCount, mode, recentFalseSkipSignals, traitProfileJSON,
                   title, adDurationStatsJSON, networkId, daiStitchNetwork, daiExpected,
                   detectorTrustJSON
            FROM podcast_profiles WHERE podcastId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, podcastId)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return PodcastProfile(
            podcastId: text(stmt, 0),
            sponsorLexicon: optionalText(stmt, 1),
            normalizedAdSlotPriors: optionalText(stmt, 2),
            repeatedCTAFragments: optionalText(stmt, 3),
            jingleFingerprints: optionalText(stmt, 4),
            implicitFalsePositiveCount: Int(sqlite3_column_int(stmt, 5)),
            skipTrustScore: sqlite3_column_double(stmt, 6),
            observationCount: Int(sqlite3_column_int(stmt, 7)),
            mode: text(stmt, 8),
            recentFalseSkipSignals: Int(sqlite3_column_int(stmt, 9)),
            traitProfileJSON: optionalText(stmt, 10),
            title: optionalText(stmt, 11),
            adDurationStatsJSON: optionalText(stmt, 12),
            networkId: optionalText(stmt, 13),
            daiStitchNetwork: optionalText(stmt, 14),
            daiExpected: optionalInt(stmt, 15).map { $0 != 0 },
            // playhead-gard: index 16 — append-only, same rule as every
            // additive column above.
            detectorTrustJSON: optionalText(stmt, 16)
        )
    }

    /// playhead-spxs: fetch all profiles whose `networkId` matches.
    /// Used by `AdDetectionService.resolveEpisodePriors` to gather the
    /// per-show inputs that `NetworkPriorsBuilder` rolls up into a
    /// network-level `NetworkPriors` aggregate.
    ///
    /// Returns an empty array when no profile in the store has been
    /// tagged with the supplied `networkId` (the resolver gracefully
    /// falls through to trait/show-local/global tiers in that case).
    /// Same column ordering as `fetchProfile` so the positional decoder
    /// matches.
    ///
    /// Defense-in-depth: an empty-string `networkId` short-circuits
    /// before the SQL bind. The production caller in
    /// `AdDetectionService.resolveEpisodePriors` already guards on
    /// `!networkId.isEmpty`, but a future caller or a corrupted profile
    /// row that decoded `networkId` as `""` would otherwise match every
    /// row whose column is the empty string — producing a phantom
    /// network of mis-grouped shows. Empty-string is never a valid
    /// network identifier, so we treat it as "no network".
    func fetchProfiles(forNetworkId networkId: String) throws -> [PodcastProfile] {
        guard !networkId.isEmpty else { return [] }
        let sql = """
            SELECT podcastId, sponsorLexicon, normalizedAdSlotPriors, repeatedCTAFragments,
                   jingleFingerprints, implicitFalsePositiveCount, skipTrustScore,
                   observationCount, mode, recentFalseSkipSignals, traitProfileJSON,
                   title, adDurationStatsJSON, networkId, daiStitchNetwork, daiExpected,
                   detectorTrustJSON
            FROM podcast_profiles WHERE networkId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, networkId)
        var profiles: [PodcastProfile] = []
        while sqlite3_step(stmt) == SQLITE_ROW {
            profiles.append(
                PodcastProfile(
                    podcastId: text(stmt, 0),
                    sponsorLexicon: optionalText(stmt, 1),
                    normalizedAdSlotPriors: optionalText(stmt, 2),
                    repeatedCTAFragments: optionalText(stmt, 3),
                    jingleFingerprints: optionalText(stmt, 4),
                    implicitFalsePositiveCount: Int(sqlite3_column_int(stmt, 5)),
                    skipTrustScore: sqlite3_column_double(stmt, 6),
                    observationCount: Int(sqlite3_column_int(stmt, 7)),
                    mode: text(stmt, 8),
                    recentFalseSkipSignals: Int(sqlite3_column_int(stmt, 9)),
                    traitProfileJSON: optionalText(stmt, 10),
                    title: optionalText(stmt, 11),
                    adDurationStatsJSON: optionalText(stmt, 12),
                    networkId: optionalText(stmt, 13),
                    daiStitchNetwork: optionalText(stmt, 14),
                    daiExpected: optionalInt(stmt, 15).map { $0 != 0 },
                    detectorTrustJSON: optionalText(stmt, 16)
                )
            )
        }
        return profiles
    }

    /// playhead-i9dj: persist the human-readable show title on the
    /// `podcast_profiles` row so an exported `analysis.sqlite` is
    /// legible without joining to the SwiftData side.
    ///
    /// Lazy-create + idempotent semantics:
    ///   * If no profile row exists for `podcastId`, this method is a
    ///     no-op (the title will land on the next `upsertProfile` from
    ///     trust-scoring once the title parameter is threaded — until
    ///     then we don't materialize a title-only stub).
    ///   * If a profile row exists, the title column is overwritten
    ///     with the supplied value. Passing `nil` is a no-op (preserves
    ///     any previously-recorded title) — same conservative semantics
    ///     as ``updateAssetEpisodeTitle(id:episodeTitle:)``.
    ///
    /// - Parameters:
    ///   - podcastId: `podcast_profiles.podcastId` of the row to update.
    ///   - title: the show title to persist, or `nil` for a no-op.
    func updateProfileTitle(podcastId: String, title: String?) throws {
        guard let title else { return }

        let sql = "UPDATE podcast_profiles SET title = ? WHERE podcastId = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, title)
        bind(stmt, 2, podcastId)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// playhead-xsdz.71 (Signal 1): persist the show-level DAI-stitch
    /// classification (network + DAI-EXPECTED prior) derived from the enclosure
    /// download's redirect chain. Column-specific setter that writes ONLY the
    /// two columns it owns — `upsertProfile` never touches them, so a profile
    /// rebuild (trust-scoring / priors update) preserves the classification.
    ///
    /// ONCE-PER-SHOW / IDEMPOTENT / NO-CREATE semantics, all enforced in one
    /// statement:
    ///   * `WHERE podcastId = ?` — a plain UPDATE, so a brand-new show whose
    ///     `podcast_profiles` row does not exist yet is a benign no-op (mirrors
    ///     `updateProfileTitle`). A later download, once the row exists, records
    ///     it.
    ///   * `AND daiStitchNetwork IS NULL` — the once-per-show gate: the first
    ///     observation wins and later observations (which may see a truncated
    ///     chain) cannot overwrite it. Re-recording is a cheap no-op.
    ///
    /// - Parameters:
    ///   - podcastId: `podcast_profiles.podcastId` of the row to update.
    ///   - daiStitchNetwork: `DAIStitchNetwork.rawValue` of the classification.
    ///   - daiExpected: whether DAI is expected for the show (stored 1/0).
    func updateProfileDAIStitch(
        podcastId: String,
        daiStitchNetwork: String,
        daiExpected: Bool
    ) throws {
        let sql = """
            UPDATE podcast_profiles
            SET daiStitchNetwork = ?, daiExpected = ?
            WHERE podcastId = ? AND daiStitchNetwork IS NULL
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, daiStitchNetwork)
        bind(stmt, 2, daiExpected ? 1 : 0)
        bind(stmt, 3, podcastId)
        try step(stmt, expecting: SQLITE_DONE)
    }

    // MARK: - CRUD: podcast_planner_state (bd-m8k)

    /// bd-m8k: Returns the persisted `PodcastPlannerState` for `podcastId`, or
    /// `nil` if no row has been created for this podcast yet. Callers should
    /// treat `nil` as the conservative cold-start default
    /// (`observedEpisodeCount = 0`, `stablePrecisionFlag = false`,
    /// `episodesSinceLastFullRescan = 0`) — the migration deliberately leaves
    /// the table empty and rows are created lazily on first observation.
    func fetchPodcastPlannerState(podcastId: String) throws -> PodcastPlannerState? {
        // historical: stored as "precision*"; semantically recall
        // Cycle 4 B4: two new persisted counters appended at the end.
        let sql = """
            SELECT podcastId,
                   observedEpisodeCount,
                   episodesSinceLastFullRescan,
                   stablePrecisionFlag,
                   lastFullRescanAt,
                   precisionSample1,
                   precisionSample2,
                   precisionSample3,
                   precisionSampleCount,
                   episodesObservedWithoutSampleCount,
                   narrowingAllPhasesEmptyEpisodeCount
            FROM podcast_planner_state
            WHERE podcastId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, podcastId)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }

        // Cycle 2 Rev4-M3: clamp the persisted sample count into the valid
        // range and log loudly when the clamp fires. A row that has
        // `precisionSampleCount` outside `[0, plannerRecallRingSize]` is
        // either a bug, a manual SQL edit, or a corrupted file — either way
        // operators should see it in Console.app instead of the store
        // silently rounding past it.
        let rawSampleCount = Int(sqlite3_column_int(stmt, 8))
        let sampleCount = max(0, min(Self.plannerRecallRingSize, rawSampleCount))
        if rawSampleCount != sampleCount {
            logger.error(
                "podcast_planner_state.precisionSampleCount=\(rawSampleCount, privacy: .public) out of range [0, \(Self.plannerRecallRingSize, privacy: .public)] for podcast=\(podcastId, privacy: .public); clamped to \(sampleCount, privacy: .public)"
            )
        }
        // Samples are stored oldest → newest in columns 5/6/7. We hand back
        // exactly `sampleCount` doubles so callers cannot accidentally treat
        // a NULL slot as a real measurement.
        var samples: [Double] = []
        samples.reserveCapacity(sampleCount)
        for offset in 0..<sampleCount {
            if let value = optionalDouble(stmt, Int32(5 + offset)) {
                samples.append(value)
            }
        }

        // Cycle 4 B4: columns 9/10 are the Cycle-4 additions. Legacy rows
        // default-decode to 0 thanks to `DEFAULT 0` on both columns —
        // SQLite hands back the column default for NULL-absent reads.
        let episodesObservedWithoutSampleCount = Int(sqlite3_column_int(stmt, 9))
        let narrowingAllPhasesEmptyEpisodeCount = Int(sqlite3_column_int(stmt, 10))

        return PodcastPlannerState(
            podcastId: text(stmt, 0),
            observedEpisodeCount: Int(sqlite3_column_int(stmt, 1)),
            episodesSinceLastFullRescan: Int(sqlite3_column_int(stmt, 2)),
            // historical: stored as "stablePrecisionFlag"; semantically recall
            stableRecallFlag: sqlite3_column_int(stmt, 3) != 0,
            lastFullRescanAt: optionalDouble(stmt, 4),
            // historical: stored as "precisionSamples"; semantically recall
            recallSamples: samples,
            episodesObservedWithoutSampleCount: episodesObservedWithoutSampleCount,
            narrowingAllPhasesEmptyEpisodeCount: narrowingAllPhasesEmptyEpisodeCount
        )
    }

    /// bd-m8k: Records that a backfill pass for `podcastId` has just completed
    /// and returns the updated state.
    ///
    /// **Lazy creation:** if no row exists for `podcastId`, one is inserted at
    /// cold-start defaults before the bookkeeping below is applied. This is
    /// the only path that materializes a row — there is no migration backfill
    /// and no separate `upsert` API.
    ///
    /// **Bookkeeping rules** (per the bd-m8k design field):
    /// - `observedEpisodeCount` is incremented by 1 on every call.
    /// - `wasFullRescan == true` — and, per playhead-hvk0, `fullRescanReadEpisode`
    ///   is not `false`: `episodesSinceLastFullRescan` resets to 0,
    ///   `lastFullRescanAt` is updated, and (when `fullRescanPrecisionSample` is
    ///   non-nil) the sample is appended to the recall ring with the oldest entry
    ///   dropped if the ring is already full.
    /// - `wasFullRescan == false`: `episodesSinceLastFullRescan` is
    ///   incremented; the recall ring is left untouched. A recall
    ///   sample passed alongside a non-full-rescan call is ignored (the
    ///   targeted-with-audit pass cannot measure recall against itself).
    /// - `stableRecallFlag` is recomputed from the post-update state on
    ///   every call: it is true iff
    ///   `observedEpisodeCount >= plannerStableObservedEpisodeFloor` AND the
    ///   ring is full (`plannerRecallRingSize` samples) AND every sample
    ///   in the ring is `>= plannerRecallThreshold`. If any condition
    ///   fails the flag is forced false, even if a previous write set it to
    ///   true (the ring shrinks back to false on regression).
    /// - Cycle 4 B4: `incrementEpisodesObservedWithoutSample` and
    ///   `incrementNarrowingAllPhasesEmpty` are independent per-podcast
    ///   counters. When true, the persisted counters are read-modify-written
    ///   under the same transaction as the rest of the bookkeeping. Both
    ///   flags are orthogonal — an ad-free full rescan passes
    ///   `incrementEpisodesObservedWithoutSample = true` and an all-phases-
    ///   empty targeted run passes `incrementNarrowingAllPhasesEmpty = true`.
    ///   A full rescan can pass both (ad-free episode where narrowing was
    ///   also empty).
    /// - playhead-hvk0: `fullRescanReadEpisode` carries the full rescan's
    ///   MEASURED read evidence. `nil` (the default, and the only value any
    ///   pre-hvk0 caller passes) leaves the flag derivation byte-identical.
    ///   `false` forces `stableRecallFlag` false for this observation — see
    ///   ``computePlannerStableFlag(observedEpisodeCount:samples:fullRescanReadEpisode:)``
    ///   for why the recall ring alone cannot certify the targeted policy. It is
    ///   deliberately NOT persisted as its own column: the value is re-supplied
    ///   by every subsequent full-coverage observation, and a demoted show is
    ///   planned with a full-episode phase, so there is no observation path that
    ///   could read a stale value. `false` suppresses ALL THREE effects of a full
    ///   rescan — the recall-ring append, the `episodesSinceLastFullRescan` /
    ///   `lastFullRescanAt` reset, and the stable flag — because a rescan that
    ///   did not read the episode certified nothing and re-validated nothing.
    ///   Suppressing the clock reset is what lets an ALREADY-promoted show
    ///   recover; see the `rescanRevalidated` block below.
    @discardableResult
    func recordPodcastEpisodeObservation(
        podcastId: String,
        wasFullRescan: Bool,
        fullRescanPrecisionSample: Double? = nil,
        incrementEpisodesObservedWithoutSample: Bool = false,
        incrementNarrowingAllPhasesEmpty: Bool = false,
        fullRescanReadEpisode: Bool? = nil,
        now: Double
    ) throws -> PodcastPlannerState {
        // Wrap the read-modify-write in a transaction so a concurrent
        // observation for the same podcast cannot interleave a stale read
        // with our write. SQLite's busy_timeout already serializes writers,
        // but BEGIN IMMEDIATE upgrades the lock immediately so two callers
        // hitting the same row see SQLITE_BUSY rather than racing on the
        // counter.
        try exec("BEGIN IMMEDIATE")
        do {
            let prior = try fetchPodcastPlannerState(podcastId: podcastId)
            // historical: stored as "precision*"; semantically recall
            let priorSamples = prior?.recallSamples ?? []

            let newObservedCount = (prior?.observedEpisodeCount ?? 0) + 1
            let newEpisodesSince: Int
            let newLastFullRescanAt: Double?
            var newSamples = priorSamples

            // playhead-hvk0: a rescan RE-VALIDATES the show — and so restarts the
            // periodic re-validation clock — only when it can be shown to have
            // read its episode. `nil` read evidence (gate off, or a non-rescan
            // observation) preserves the pre-hvk0 meaning exactly.
            //
            // This is the term that lets an ALREADY-promoted show recover. The
            // recall-sample gate above stops a NEW show being promoted on a
            // self-measurement, but it cannot demote one that already was: a
            // promoted show plans `targetedWithAudit`, whose observations carry
            // no rescan and therefore no read evidence, so the flag would derive
            // from the untouched ring forever. Measured on the 2026-07-29 device
            // pull, `feeds.simplecast.com/dHoohVNH` sits at
            // `episodesSinceLastFullRescan = 4` precisely BECAUSE rescans that
            // examined 82–167 s of a 1,503–4,379 s episode kept resetting this
            // counter. Without those resets the counter reaches the periodic
            // interval, `shouldUsePeriodicFullRescan` fires ahead of the targeted
            // branch, and the show is back on a full-coverage plan.
            //
            // The steady state for a show whose scans never complete is
            // "periodic full rescan on every episode". That is the `reset(context:)`
            // doc's "deadlocked policy loop" reached deliberately, and it is the
            // correct state: a show whose full scans cannot finish has never
            // earned narrowing. It costs no extra passes — a full-coverage plan
            // is ONE `fullEpisodeScan` job, and M-5 skips it when complete — and
            // the counter's growth past the interval has no further effect, so
            // there is nothing here to run away.
            let rescanRevalidated = wasFullRescan && fullRescanReadEpisode != false
            // playhead-hvk0: the ring advances only on a rescan that re-validated.
            // This is the SINGLE place the read-evidence gate touches the ring —
            // the runner computes the sample unconditionally and hands it over,
            // so a caller cannot get the gate half-right. Guarding only the flag
            // and not the ring would be a latent bug rather than a nicety: a
            // circular 1.0 would still be BANKED, and the next observation with
            // `true` (or with the gate off) would promote the show off samples the
            // store had already judged uncertifiable.
            if rescanRevalidated {
                // Cycle 2 C4: parameter is named `fullRescanPrecisionSample`
                // for legacy compatibility but the value semantically is a
                // recall sample. Ad-free episodes pass nil and the ring is
                // intentionally NOT advanced (no fake 1.0).
                if let sample = fullRescanPrecisionSample {
                    newSamples.append(sample)
                    while newSamples.count > Self.plannerRecallRingSize {
                        newSamples.removeFirst()
                    }
                }
                newEpisodesSince = 0
                newLastFullRescanAt = now
            } else {
                newEpisodesSince = (prior?.episodesSinceLastFullRescan ?? 0) + 1
                newLastFullRescanAt = prior?.lastFullRescanAt
                // Intentionally do NOT touch the recall ring on
                // non-full-rescan observations — see doc comment above.
            }

            // playhead-hvk0: the read-evidence term only ever applies to a full
            // rescan. A targeted observation has no rescan to certify, so it
            // passes `nil` through and the flag derives from the ring alone.
            let stableFlag = Self.computePlannerStableFlag(
                observedEpisodeCount: newObservedCount,
                samples: newSamples,
                fullRescanReadEpisode: wasFullRescan ? fullRescanReadEpisode : nil
            )

            // Cycle 4 B4: per-podcast counters. Read prior value (0 for
            // missing rows via the struct default above) and bump under
            // the same BEGIN IMMEDIATE that guards the rest of the
            // bookkeeping.
            let newEpisodesObservedWithoutSample =
                (prior?.episodesObservedWithoutSampleCount ?? 0)
                + (incrementEpisodesObservedWithoutSample ? 1 : 0)
            let newNarrowingAllPhasesEmptyEpisodes =
                (prior?.narrowingAllPhasesEmptyEpisodeCount ?? 0)
                + (incrementNarrowingAllPhasesEmpty ? 1 : 0)

            try writePodcastPlannerStateRow(
                podcastId: podcastId,
                observedEpisodeCount: newObservedCount,
                episodesSinceLastFullRescan: newEpisodesSince,
                stableRecallFlag: stableFlag,
                lastFullRescanAt: newLastFullRescanAt,
                samples: newSamples,
                episodesObservedWithoutSampleCount: newEpisodesObservedWithoutSample,
                narrowingAllPhasesEmptyEpisodeCount: newNarrowingAllPhasesEmptyEpisodes
            )

            try exec("COMMIT")

            return PodcastPlannerState(
                podcastId: podcastId,
                observedEpisodeCount: newObservedCount,
                episodesSinceLastFullRescan: newEpisodesSince,
                // historical: stored as "stablePrecisionFlag"; semantically recall
                stableRecallFlag: stableFlag,
                lastFullRescanAt: newLastFullRescanAt,
                // historical: stored as "precisionSamples"; semantically recall
                recallSamples: newSamples,
                episodesObservedWithoutSampleCount: newEpisodesObservedWithoutSample,
                narrowingAllPhasesEmptyEpisodeCount: newNarrowingAllPhasesEmptyEpisodes
            )
        } catch {
            try? exec("ROLLBACK")
            throw error
        }
    }

    /// bd-m8k: pure helper exposed for tests. Computes the stable-recall
    /// flag from a post-update `(observedEpisodeCount, samples)` tuple. The
    /// flag is true iff:
    /// 1. `observedEpisodeCount >= plannerStableObservedEpisodeFloor` (5), AND
    /// 2. The recall ring contains exactly `plannerRecallRingSize` (3)
    ///    samples, AND
    /// 3. Every sample is `>= plannerRecallThreshold` (0.85).
    ///
    /// The "exactly 3 samples" requirement is deliberate: a freshly
    /// observed podcast with one stellar recall sample must not flip the
    /// flag — we want at least three full-rescan recall measurements
    /// before trusting the targeted-with-audit branch.
    nonisolated static func computePlannerStableFlag(
        observedEpisodeCount: Int,
        samples: [Double]
    ) -> Bool {
        guard observedEpisodeCount >= plannerStableObservedEpisodeFloor else { return false }
        guard samples.count >= plannerRecallRingSize else { return false }
        return samples.allSatisfy { $0 >= plannerRecallThreshold }
    }

    /// playhead-hvk0: the stable-recall flag, with the full-rescan READ
    /// EVIDENCE applied on top of the ring.
    ///
    /// **Why the ring alone is not enough.** A recall sample answers "of the
    /// ad lines the FULL RESCAN found, what fraction would the targeted phases
    /// also have scanned". Its denominator is produced by the rescan itself, so
    /// a rescan that read almost none of the episode finds almost no ad lines
    /// and the targeted phases trivially cover them — the sample reads 1.0.
    /// Measured on the 2026-07-29 device pull: every `fullEpisodeScan` on
    /// `feeds.simplecast.com/dHoohVNH` examined 82–167 s of episodes 1,503–4,379 s
    /// long (2–5%), and those runs are what put three 1.0 samples in the ring and
    /// promoted the whole show to `targetedWithAudit`. Conditioning on a scan and
    /// then concluding the scan's targeting works is circular — the same trap
    /// playhead-4xqf's original N=12 pair-only conclusion fell into.
    ///
    /// So the ring is necessary and not sufficient: a rescan may only CERTIFY the
    /// targeted policy if it measurably read the episode
    /// (``AnalysisCoverageSummary/adScanFraction`` at or above
    /// ``AnalysisJobRunner/semanticBackfillSufficientAdScanFraction`` — the SAME
    /// floor the runner's skip predicate, the re-drive mint and the library ✓ use;
    /// playhead-csbq pinned that ruler and this deliberately introduces no second
    /// coverage measure).
    ///
    /// - Parameter fullRescanReadEpisode: `nil` on any observation that is not a
    ///   full rescan, or when the caller is not applying the gate — the flag then
    ///   derives from the ring exactly as it did pre-hvk0. `false` means a full
    ///   rescan ran and could NOT be shown to have read the episode (short scan,
    ///   unmeasurable coverage, or a failed read): the flag is forced false.
    ///   `true` means it did.
    ///
    /// **Direction of the error, on purpose.** Every uncertain input resolves to
    /// "not certified", which can only ever route future episodes to a
    /// full-episode plan — the plan that INTENDS to read the whole episode. It is
    /// not a guarantee that more audio is read: a single-job full scan dies on a
    /// `.pass`-scoped failure where three targeted jobs would not (see
    /// `BackfillJobRunner.fullRescanReadEpisode(assetId:)`). This helper cannot
    /// cause a pass, a retry or a widen; it only decides which plan an
    /// already-caused pass produces.
    ///
    /// **Not sticky, and it does not need to be.** A demotion routes the show's
    /// next episode to a full-coverage policy, which supplies this input again —
    /// so the flag cannot flap back through a targeted run it has itself made
    /// unreachable. A rescan that finally reads its episode restores the flag
    /// from the untouched ring.
    nonisolated static func computePlannerStableFlag(
        observedEpisodeCount: Int,
        samples: [Double],
        fullRescanReadEpisode: Bool?
    ) -> Bool {
        if fullRescanReadEpisode == false { return false }
        return computePlannerStableFlag(
            observedEpisodeCount: observedEpisodeCount,
            samples: samples
        )
    }

    private func writePodcastPlannerStateRow(
        podcastId: String,
        observedEpisodeCount: Int,
        episodesSinceLastFullRescan: Int,
        // Cycle 6 B6 L: parameter name follows the "recall" semantic the
        // cycle-4 rename pass established. The underlying SQLite column is
        // still `stablePrecisionFlag` for backwards compatibility.
        stableRecallFlag: Bool,
        lastFullRescanAt: Double?,
        samples: [Double],
        episodesObservedWithoutSampleCount: Int,
        narrowingAllPhasesEmptyEpisodeCount: Int
    ) throws {
        // Pad the samples array out to the fixed-width ring slots so we can
        // unconditionally bind 3 columns regardless of how many samples we
        // have in hand.
        var ring: [Double?] = Array(repeating: nil, count: Self.plannerRecallRingSize)
        for (idx, value) in samples.enumerated()
        where idx < Self.plannerRecallRingSize {
            ring[idx] = value
        }

        // Cycle 4 B4: two new persisted counters appended.
        let sql = """
            INSERT INTO podcast_planner_state
            (podcastId, observedEpisodeCount, episodesSinceLastFullRescan,
             stablePrecisionFlag, lastFullRescanAt,
             precisionSample1, precisionSample2, precisionSample3,
             precisionSampleCount,
             episodesObservedWithoutSampleCount,
             narrowingAllPhasesEmptyEpisodeCount)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(podcastId) DO UPDATE SET
                observedEpisodeCount                = excluded.observedEpisodeCount,
                episodesSinceLastFullRescan         = excluded.episodesSinceLastFullRescan,
                stablePrecisionFlag                 = excluded.stablePrecisionFlag,
                lastFullRescanAt                    = excluded.lastFullRescanAt,
                precisionSample1                    = excluded.precisionSample1,
                precisionSample2                    = excluded.precisionSample2,
                precisionSample3                    = excluded.precisionSample3,
                precisionSampleCount                = excluded.precisionSampleCount,
                episodesObservedWithoutSampleCount  = excluded.episodesObservedWithoutSampleCount,
                narrowingAllPhasesEmptyEpisodeCount = excluded.narrowingAllPhasesEmptyEpisodeCount
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, podcastId)
        bind(stmt, 2, observedEpisodeCount)
        bind(stmt, 3, episodesSinceLastFullRescan)
        bind(stmt, 4, stableRecallFlag ? 1 : 0)
        bind(stmt, 5, lastFullRescanAt)
        bind(stmt, 6, ring[0])
        bind(stmt, 7, ring[1])
        bind(stmt, 8, ring[2])
        bind(stmt, 9, samples.count)
        bind(stmt, 10, episodesObservedWithoutSampleCount)
        bind(stmt, 11, narrowingAllPhasesEmptyEpisodeCount)
        try step(stmt, expecting: SQLITE_DONE)
    }

    // MARK: - CRUD: preview_budgets

    func upsertBudget(_ budget: PreviewBudget) throws {
        let sql = """
            INSERT INTO preview_budgets
            (canonicalEpisodeKey, consumedAnalysisSeconds, graceBreakWindow, lastUpdated)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(canonicalEpisodeKey) DO UPDATE SET
                consumedAnalysisSeconds = excluded.consumedAnalysisSeconds,
                graceBreakWindow = excluded.graceBreakWindow,
                lastUpdated = excluded.lastUpdated
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, budget.canonicalEpisodeKey)
        bind(stmt, 2, budget.consumedAnalysisSeconds)
        bind(stmt, 3, budget.graceBreakWindow)
        bind(stmt, 4, budget.lastUpdated)
        try step(stmt, expecting: SQLITE_DONE)
    }

    func fetchBudget(key: String) throws -> PreviewBudget? {
        let sql = "SELECT * FROM preview_budgets WHERE canonicalEpisodeKey = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, key)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return PreviewBudget(
            canonicalEpisodeKey: text(stmt, 0),
            consumedAnalysisSeconds: sqlite3_column_double(stmt, 1),
            graceBreakWindow: sqlite3_column_double(stmt, 2),
            lastUpdated: sqlite3_column_double(stmt, 3)
        )
    }

    // MARK: - CRUD: analysis_jobs

    @discardableResult
    func insertJob(_ job: AnalysisJob) throws -> Bool {
        // playhead-uzdq: generationID + schedulerEpoch are appended.
        // Defaults on the AnalysisJob init mean legacy callers that
        // don't pass them insert the "no-lease" sentinels ('' and 0),
        // matching the column DEFAULTs for pre-existing rows.
        let sql = """
            INSERT OR IGNORE INTO analysis_jobs
            (jobId, jobType, episodeId, podcastId, analysisAssetId, workKey,
             sourceFingerprint, downloadId, priority, desiredCoverageSec,
             featureCoverageSec, transcriptCoverageSec, cueCoverageSec,
             state, attemptCount, nextEligibleAt, leaseOwner, leaseExpiresAt,
             lastErrorCode, createdAt, updatedAt, generationID, schedulerEpoch)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, job.jobId)
        bind(stmt, 2, job.jobType)
        bind(stmt, 3, job.episodeId)
        bind(stmt, 4, job.podcastId)
        bind(stmt, 5, job.analysisAssetId)
        bind(stmt, 6, job.workKey)
        bind(stmt, 7, job.sourceFingerprint)
        bind(stmt, 8, job.downloadId)
        bind(stmt, 9, job.priority)
        bind(stmt, 10, job.desiredCoverageSec)
        bind(stmt, 11, job.featureCoverageSec)
        bind(stmt, 12, job.transcriptCoverageSec)
        bind(stmt, 13, job.cueCoverageSec)
        bind(stmt, 14, job.state)
        bind(stmt, 15, job.attemptCount)
        bind(stmt, 16, job.nextEligibleAt)
        bind(stmt, 17, job.leaseOwner)
        bind(stmt, 18, job.leaseExpiresAt)
        bind(stmt, 19, job.lastErrorCode)
        bind(stmt, 20, job.createdAt)
        bind(stmt, 21, job.updatedAt)
        bind(stmt, 22, job.generationID)
        bind(stmt, 23, job.schedulerEpoch)
        try step(stmt, expecting: SQLITE_DONE)
        return sqlite3_changes(db) > 0
    }

    /// Atomically removes scheduler artifacts owned by a cached download that
    /// the user deleted. The journal subquery is evaluated before the job rows
    /// are removed so only generations belonging to those jobs are retired;
    /// unrelated historical episode journal entries remain intact.
    @discardableResult
    func deleteAnalysisJobsForRemovedDownload(
        episodeId: String,
        downloadId: String
    ) throws -> Set<String> {
        try exec("BEGIN IMMEDIATE")
        do {
            let select = try prepare(
                """
                SELECT jobId
                FROM analysis_jobs
                WHERE episodeId = ? AND downloadId = ?
                """
            )
            bind(select, 1, episodeId)
            bind(select, 2, downloadId)
            var jobIDs = Set<String>()
            while sqlite3_step(select) == SQLITE_ROW {
                jobIDs.insert(text(select, 0))
            }
            sqlite3_finalize(select)

            let deleteJournal = try prepare(
                """
                DELETE FROM work_journal
                WHERE episode_id = ?
                  AND generation_id IN (
                    SELECT generationID
                    FROM analysis_jobs
                    WHERE episodeId = ? AND downloadId = ?
                  )
                """
            )
            bind(deleteJournal, 1, episodeId)
            bind(deleteJournal, 2, episodeId)
            bind(deleteJournal, 3, downloadId)
            try step(deleteJournal, expecting: SQLITE_DONE)
            sqlite3_finalize(deleteJournal)

            let deleteJobs = try prepare(
                """
                DELETE FROM analysis_jobs
                WHERE episodeId = ? AND downloadId = ?
                """
            )
            bind(deleteJobs, 1, episodeId)
            bind(deleteJobs, 2, downloadId)
            try step(deleteJobs, expecting: SQLITE_DONE)
            sqlite3_finalize(deleteJobs)
            try exec("COMMIT")
            return jobIDs
        } catch {
            try? exec("ROLLBACK")
            throw error
        }
    }

    /// Deletes only the job generation minted by an enqueue that lost its
    /// ownership race. Unlike the episode-wide cache-removal cleanup, this
    /// must not touch a fresh re-download that may already be enqueuing.
    func deleteRetiredAnalysisEnqueue(
        jobId: String,
        generationID: String
    ) throws {
        try exec("BEGIN IMMEDIATE")
        do {
            let deleteJournal = try prepare(
                """
                DELETE FROM work_journal
                WHERE generation_id = ?
                """
            )
            bind(deleteJournal, 1, generationID)
            try step(deleteJournal, expecting: SQLITE_DONE)
            sqlite3_finalize(deleteJournal)

            let deleteJob = try prepare(
                """
                DELETE FROM analysis_jobs
                WHERE jobId = ? AND generationID = ?
                """
            )
            bind(deleteJob, 1, jobId)
            bind(deleteJob, 2, generationID)
            try step(deleteJob, expecting: SQLITE_DONE)
            sqlite3_finalize(deleteJob)
            try exec("COMMIT")
        } catch {
            try? exec("ROLLBACK")
            throw error
        }
    }

    func fetchJob(byId jobId: String) throws -> AnalysisJob? {
        let sql = "SELECT * FROM analysis_jobs WHERE jobId = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, jobId)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return readJob(stmt)
    }

    /// playhead-y8f3: the row occupying a given `workKey`, or `nil` when the key
    /// is free.
    ///
    /// `workKey` is `TEXT NOT NULL UNIQUE` with an index (`idx_jobs_workkey`),
    /// so this is a single indexed read and returns at most one row. It exists
    /// because `insertJob` is `INSERT OR IGNORE`: a caller that gets `false`
    /// back knows only that SOMETHING already owns the key, and the whole
    /// question — was the re-request swallowed by a live job, by a clean
    /// terminal, or by an attempt-cap dead end that should be re-requested at a
    /// fresh ordinal — needs the row itself. Looking up by key rather than by
    /// episode also keeps the answer pinned to the audio the caller actually has
    /// on disk: an episode can carry rows for several fingerprints, and
    /// `fetchLatestJobForEpisode` would happily return one describing different
    /// bytes.
    func fetchJob(byWorkKey workKey: String) throws -> AnalysisJob? {
        let sql = "SELECT * FROM analysis_jobs WHERE workKey = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, workKey)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return readJob(stmt)
    }

    /// Returns the most-recently-updated `analysis_jobs` row for an
    /// episode. Primarily used by the playhead-44h1 foreground-assist
    /// hand-off so the BG task expiration / completion paths can
    /// resolve the current `{generationID, schedulerEpoch}` and append
    /// a terminal WorkJournal row keyed by the episode alone. Returns
    /// `nil` when the episode has no row.
    func fetchLatestJobForEpisode(_ episodeId: String) throws -> AnalysisJob? {
        let sql = """
            SELECT * FROM analysis_jobs
            WHERE episodeId = ?
            ORDER BY updatedAt DESC, rowid DESC
            LIMIT 1
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, episodeId)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return readJob(stmt)
    }

    /// Bulk latest-job map keyed by `episodeId`. Mirrors
    /// `fetchLatestJobForEpisode(_:)` for hot Activity/diagnostics paths
    /// that need terminal-job state for many visible episodes.
    func fetchLatestJobByEpisodeIdMap(episodeIds: Set<String>) throws -> [String: AnalysisJob] {
        guard !episodeIds.isEmpty else { return [:] }
        let chunkSize = 500
        var results: [String: AnalysisJob] = [:]
        results.reserveCapacity(episodeIds.count)

        let allIds = Array(episodeIds)
        var index = 0
        while index < allIds.count {
            let end = min(index + chunkSize, allIds.count)
            let slice = Array(allIds[index..<end])
            let placeholders = slice.map { _ in "?" }.joined(separator: ", ")
            let sql = """
                SELECT * FROM analysis_jobs
                WHERE episodeId IN (\(placeholders))
                ORDER BY updatedAt DESC, rowid DESC
                """
            let stmt = try prepare(sql)
            for (i, id) in slice.enumerated() {
                bind(stmt, Int32(i + 1), id)
            }
            while sqlite3_step(stmt) == SQLITE_ROW {
                let job = readJob(stmt)
                if results[job.episodeId] == nil {
                    results[job.episodeId] = job
                }
            }
            sqlite3_finalize(stmt)
            index = end
        }

        return results
    }

    /// - Parameter nowLanePriorityFloor: playhead-ewag. Lowest `priority` that
    ///   counts as Now-lane work and is therefore selectable even when
    ///   `deferredWorkAllowed` is false; `nil` disables the carve-out entirely
    ///   (pre-ewag behaviour).
    ///
    ///   This exists because `deferredWorkAllowed` is a single bit derived from
    ///   `allowSoonLane || allowBackgroundLane`, and BOTH are false at
    ///   `QualityProfile.serious`. Without the carve-out the query hides every
    ///   non-playback row on a warm device — including the explicit downloads
    ///   the user is waiting on — so the scheduler cannot even see the work it
    ///   is supposed to admit, and no amount of post-selection lane logic can
    ///   recover a row that was never selected.
    ///
    ///   The floor is passed in rather than hardcoded so the number lives in
    ///   exactly one place (`AnalysisWorkScheduler.nowLanePriorityFloor`,
    ///   which also defines `AnalysisJob.schedulerLane`). A second literal in a
    ///   query string is how the SQL and the Swift lane derivation drift apart.
    func fetchNextEligibleJob(
        deferredWorkAllowed: Bool,
        nowLanePriorityFloor: Int? = nil,
        t0ThresholdSec: Double,
        now: TimeInterval
    ) throws -> AnalysisJob? {
        // T0 jobs: playback jobs that have zero coverage — always eligible.
        // Deferred jobs: backfill/preAnalysis require EITHER the caller's
        // shared admission-policy gate to allow deferred work OR the row to be
        // Now-lane, and nextEligibleAt <= now (or NULL).
        let sql = """
            SELECT * FROM analysis_jobs
            WHERE (
                (state IN ('queued', 'paused')
                  AND (leaseOwner IS NULL OR leaseExpiresAt < ?)
                  AND (nextEligibleAt IS NULL OR nextEligibleAt <= ?))
                OR (state = 'failed' AND nextEligibleAt IS NOT NULL AND nextEligibleAt <= ?)
              )
              AND (
                (jobType = 'playback' AND featureCoverageSec < ?)
                OR (
                  (? = 1 OR (? = 1 AND priority >= ?))
                  AND (nextEligibleAt IS NULL OR nextEligibleAt <= ?)
                )
              )
            ORDER BY priority DESC, createdAt ASC
            LIMIT 1
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, now)
        bind(stmt, 2, now)
        bind(stmt, 3, now)
        bind(stmt, 4, t0ThresholdSec)
        bind(stmt, 5, deferredWorkAllowed ? 1 : 0)
        // A separate enable bit rather than an unreachable sentinel floor:
        // `bind(_:_:Int)` narrows to `Int32`, so an `Int.max` sentinel would
        // trap at runtime the moment the carve-out was disabled.
        bind(stmt, 6, nowLanePriorityFloor == nil ? 0 : 1)
        bind(stmt, 7, nowLanePriorityFloor ?? 0)
        bind(stmt, 8, now)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return readJob(stmt)
    }

    func updateJobProgress(
        jobId: String,
        featureCoverageSec: Double,
        transcriptCoverageSec: Double,
        cueCoverageSec: Double
    ) throws {
        let sql = """
            UPDATE analysis_jobs
            SET featureCoverageSec = ?, transcriptCoverageSec = ?, cueCoverageSec = ?,
                updatedAt = ?
            WHERE jobId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, featureCoverageSec)
        bind(stmt, 2, transcriptCoverageSec)
        bind(stmt, 3, cueCoverageSec)
        bind(stmt, 4, Date().timeIntervalSince1970)
        bind(stmt, 5, jobId)
        try step(stmt, expecting: SQLITE_DONE)
    }

    func updateJobState(jobId: String, state: String, nextEligibleAt: Double? = nil, lastErrorCode: String? = nil) throws {
        let sql = """
            UPDATE analysis_jobs
            SET state = ?, nextEligibleAt = ?, lastErrorCode = ?, updatedAt = ?
            WHERE jobId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, state)
        bind(stmt, 2, nextEligibleAt)
        bind(stmt, 3, lastErrorCode)
        bind(stmt, 4, Date().timeIntervalSince1970)
        bind(stmt, 5, jobId)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// playhead-dqfm: bump a still-`queued` job's `priority` for the
    /// scarcity-aware backfill re-prioritization pass. Only `priority` +
    /// `updatedAt` change — `state`, lease, coverage, `createdAt`,
    /// `generationID`, and `schedulerEpoch` are all left untouched (this is a
    /// selection nudge, NOT a lifecycle transition, so it must not disturb the
    /// FIFO `createdAt` tiebreak, orphan-recovery routing, or the lease clock).
    ///
    /// Guarded on `state = 'queued'`: if the row was leased / started running
    /// between the reconciler's read and this write, the UPDATE is a benign
    /// 0-row no-op rather than re-ranking an in-flight job.
    func updateJobPriority(jobId: String, priority: Int) throws {
        let sql = """
            UPDATE analysis_jobs
            SET priority = ?, updatedAt = ?
            WHERE jobId = ? AND state = 'queued'
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, priority)
        bind(stmt, 2, Date().timeIntervalSince1970)
        bind(stmt, 3, jobId)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// playhead-vtjx: fill in the show identity on this episode's
    /// `analysis_jobs` rows that carry SQL NULL, and report how many rows that
    /// repaired.
    ///
    /// **Why a repair exists at all.** `analysis_jobs.podcastId` was optional
    /// before playhead-kkzu made a download's show a compulsory, spelled-out
    /// field of `DownloadContext`, and on the 2026-08-08 pull it is NULL on 53
    /// of 72 rows. Every ATTRIBUTED row was created at or after kkzu
    /// (2026-08-03 17:48:58); the converse does NOT hold, and stating it that
    /// way round is load-bearing — 15 NULL rows postdate that instant on the
    /// db-evening and db-overnight pulls (the figure is 14 on db-earlypull,
    /// taken hours earlier the same day; re-derived at review R1), so this
    /// is not a closed population that one backfill drains. Two mechanisms
    /// produce them: `AnalysisJobReconciler.discoverUnEnqueuedDownloads` holds
    /// no show identity at all and mints `nil` on every reconcile pass
    /// (playhead-7ba4), and every re-mint path copies `job.podcastId` verbatim
    /// (`AnalysisWorkScheduler`'s tier successor, ad-scan re-drive and
    /// canonical-audio replacement), so a NULL is also INHERITED indefinitely.
    /// The witness for the second is 53FC53E3, whose `…:adScanRedrive:1` row
    /// minted 2026-08-08 07:55:05 carries NULL purely because its pre-kkzu
    /// parent did — four hours before F2F2FC4C's identical re-drive carried a
    /// real feed URL. That both mechanisms are still live is exactly why the
    /// reader is ``fetchRecordedPodcastId(forEpisodeId:)`` and not a
    /// latest-row-wins query: see `AnalysisCoordinator.resolveShowIdentity`.
    ///
    /// **Idempotent and non-destructive by construction.** The `podcastId IS
    /// NULL` clause is what makes both true: a second call changes nothing, and
    /// a row that already names a show is never re-pointed at another one. The
    /// caller supplies an identity recovered from the episode store, which is a
    /// SECOND observation of the same fact — it may not overrule the analysis
    /// lane's own record.
    ///
    /// **`updatedAt` is deliberately NOT touched.** This is not a lifecycle
    /// transition; it records something that was always true of the row. The
    /// column is the clock `fetchLatestJobForEpisode` orders by and the
    /// stranded-lease reaper keys on, and bumping every row of an episode to
    /// one instant would re-order "latest" and disturb both — for a write that
    /// changes no state.
    ///
    /// Whether `podcastId` is a real identity is decided ABOVE this call, at
    /// the one site that turns a resolver's answer into a key it will persist
    /// (``AnalysisCoordinator/resolveCoarseScanShowIdentity(jobPodcastId:episodeStoreIdentity:)``).
    /// Restating that policy here would be a second copy that no mutant can
    /// kill while the two agree — the shape playhead-fil5 R2 recorded when the
    /// SC09 mutant survived against exactly it.
    ///
    /// - Returns: the number of rows repaired. `0` is the steady state, and is
    ///   also what a race with a concurrent writer yields — benign either way.
    @discardableResult
    func backfillJobPodcastId(episodeId: String, podcastId: String) throws -> Int {
        let sql = """
            UPDATE analysis_jobs
            SET podcastId = ?
            WHERE episodeId = ? AND podcastId IS NULL
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, podcastId)
        bind(stmt, 2, episodeId)
        try step(stmt, expecting: SQLITE_DONE)
        return Int(sqlite3_changes(db))
    }

    /// playhead-kanf: the outcome of a user-intent lane promotion attempt.
    ///
    /// Four cases rather than a `Bool` because the caller has to distinguish
    /// *served* from *changed*: a row already sitting in the `.now` lane needs
    /// no write but has satisfied the user's request, whereas a leased row
    /// needs no write and has NOT. Collapsing those two into "no rows changed"
    /// is what would let the one-shot user-intent flag be burned without
    /// effect.
    enum UserIntentPromotion: Equatable, Sendable {
        /// The row was `queued` + unleased below the floor and is now at it.
        case promoted(jobId: String, fromPriority: Int, toPriority: Int)
        /// The row already sits at or above the floor — nothing to write, but
        /// the intent is satisfied.
        case alreadyPromoted(jobId: String, priority: Int)
        /// The row exists but is not safe to re-rank: leased, running, paused,
        /// or terminal. Deliberately NOT promoted; see the guard note below.
        case notPromotable(jobId: String, state: String, priority: Int, leased: Bool)
        /// No row occupies the key.
        case noRow
    }

    /// playhead-kanf: raise the `priority` of the still-`queued` row occupying
    /// `workKey` to the user-intent (`.now`) floor, so a tap on "Download &
    /// Analyze" preempts a starving background job instead of silently doing
    /// nothing.
    ///
    /// This exists because ``insertJob`` is `INSERT OR IGNORE` on the UNIQUE
    /// `workKey`: when the auto-pipeline already queued the episode, the
    /// scheduler's freshly-minted priority-20 job struct is discarded whole and
    /// the stored row keeps its background priority. The lane lives in the
    /// column, so promoting it has to be a write against the existing row.
    ///
    /// **The guard is `state = 'queued' AND leaseOwner IS NULL`, and both
    /// halves are load-bearing.** Re-ranking a row a worker is executing is a
    /// lease/epoch correctness decision the bead explicitly declines to make
    /// here. `state='running'` is what every lease writer sets
    /// (``acquireLease``, ``acquireLeaseWithJournal``, ``acquireEpisodeLease``),
    /// but the two conditions are not equivalent: ``fetchNextEligibleJob``
    /// selects `state IN ('queued','paused') AND (leaseOwner IS NULL OR
    /// leaseExpiresAt < ?)`, so the schema tolerates a `queued` row still
    /// carrying a stale lease. ``restampQueuedJobEpochs`` already uses this same
    /// pair as its safe-to-touch predicate. `paused` is excluded too: one
    /// promotable state keeps the rule stateable in a sentence, and the caller
    /// retains its one-shot flag so the next tap promotes the row once it
    /// returns to `queued`.
    ///
    /// Like ``updateJobPriority``, only `priority` + `updatedAt` change — this
    /// is a selection nudge, not a lifecycle transition, so `state`, the lease
    /// columns, `createdAt` (the FIFO tiebreak), `desiredCoverageSec`,
    /// `generationID` and `schedulerEpoch` are all left exactly as they were.
    ///
    /// The read and the write are one actor-isolated method, so no other store
    /// call can interleave between them; the `UPDATE` nevertheless re-states the
    /// whole predicate so it is its own compare-and-swap.
    func promoteQueuedJobToUserIntentLane(
        workKey: String,
        priority: Int,
        now: Double = Date().timeIntervalSince1970
    ) throws -> UserIntentPromotion {
        guard let job = try fetchJob(byWorkKey: workKey) else { return .noRow }
        let leased = job.leaseOwner != nil
        if job.priority >= priority {
            return .alreadyPromoted(jobId: job.jobId, priority: job.priority)
        }
        guard job.state == "queued", !leased else {
            return .notPromotable(
                jobId: job.jobId,
                state: job.state,
                priority: job.priority,
                leased: leased
            )
        }
        let sql = """
            UPDATE analysis_jobs
            SET priority = ?, updatedAt = ?
            WHERE workKey = ?
              AND state = 'queued'
              AND leaseOwner IS NULL
              AND priority < ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, priority)
        bind(stmt, 2, now)
        bind(stmt, 3, workKey)
        bind(stmt, 4, priority)
        try step(stmt, expecting: SQLITE_DONE)
        guard sqlite3_changes(db) > 0 else {
            // Lost the CAS: something claimed the row between the read and the
            // write. Report it as declined, never as promoted.
            return .notPromotable(
                jobId: job.jobId,
                state: job.state,
                priority: job.priority,
                leased: leased
            )
        }
        return .promoted(
            jobId: job.jobId,
            fromPriority: job.priority,
            toPriority: priority
        )
    }

    /// playhead-gy2s (RC-2): record why the admission gate hard-rejected a
    /// pre-analysis pass, as a durable advisory on the job row. UPDATED in
    /// place (never appended) so a job rejecting on every 30 s poll refreshes
    /// only `lastRejectAt` rather than spamming rows. Deliberately does NOT
    /// bump `updatedAt`: the advisory is orthogonal to the lease/lifecycle
    /// clock that `fetchLatestJobForEpisode` and the stranded reaper key on,
    /// and a reject is not a state transition. A 0-row UPDATE (row already
    /// gone / dispatched) is a benign no-op.
    func recordJobAdmissionReject(jobId: String, reason: String, at: Double) throws {
        let sql = """
            UPDATE analysis_jobs
            SET lastRejectReason = ?, lastRejectAt = ?
            WHERE jobId = ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, reason)
        bind(stmt, 2, at)
        bind(stmt, 3, jobId)
        try step(stmt, expecting: SQLITE_DONE)
    }

    /// playhead-gy2s (RC-2): read the admission-reject advisory for a job, or
    /// `nil` when none has been recorded (fresh row, or the job dispatched
    /// before ever being rejected). Consumed by diagnostics + the Activity
    /// surface so "Nothing running" can become "waiting for storage / Wi-Fi".
    func fetchJobAdmissionReject(jobId: String) throws -> (reason: String, at: Double)? {
        let sql = "SELECT lastRejectReason, lastRejectAt FROM analysis_jobs WHERE jobId = ?"
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, jobId)
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        guard let reason = optionalText(stmt, 0) else { return nil }
        let at = optionalDouble(stmt, 1) ?? 0
        return (reason, at)
    }

    /// playhead-gy2s (RC-3): re-stamp queued rows that were enqueued under an
    /// older scheduler epoch to the current epoch so orphan-recovery routing
    /// keys on a consistent `{generationID, schedulerEpoch}` for the current
    /// session. Queued rows hold no lease (guarded by `leaseOwner IS NULL`),
    /// so this only advances routing metadata — it never disturbs a live
    /// worker's bookkeeping. Returns the number of rows re-stamped. This is a
    /// correctness bundle for RC-3, NOT the dispatch fix: dispatch eligibility
    /// (`fetchNextEligibleJob`) never consulted `schedulerEpoch`.
    func restampQueuedJobEpochs(to currentEpoch: Int, now: Double) throws -> Int {
        let sql = """
            UPDATE analysis_jobs
            SET schedulerEpoch = ?, updatedAt = ?
            WHERE state = 'queued' AND leaseOwner IS NULL AND schedulerEpoch < ?
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, currentEpoch)
        bind(stmt, 2, now)
        bind(stmt, 3, currentEpoch)
        try step(stmt, expecting: SQLITE_DONE)
        return Int(sqlite3_changes(db))
    }

