            ON CONFLICT(showId) DO UPDATE SET alpha = excluded.alpha, beta = excluded.beta
            """
        let stmt = try prepare(sql)
        defer { sqlite3_finalize(stmt) }
        bind(stmt, 1, showId)
        bind(stmt, 2, alpha)
        bind(stmt, 3, beta)
        try step(stmt, expecting: SQLITE_DONE)
    }

